# [설정 1] 01의 적격 판정 규칙 — 한 글자도 바꾸지 않는다
# ────────────────────────────────────────────────────────────────────────
# ■ 왜 01의 필터를 그대로 써야 하나 ■
# 12가 견주는 것은 δ_fox8 과 δ_BotSim 이다. 두 δ가 다른 필터를 통과한 코퍼스에서
# 나왔다면 둘의 차이에 '자료가 다른 몫'과 '필터가 다른 몫'이 섞이고, 그 둘은
