# 01_botsim_적격검열.py 에서 복사해 온 것이고(11도 같은 방식으로 복사했다),
# 더한 것은 fox8에만 있는 필드를 쓰는 규칙 하나뿐이다([설정 2]).
#
# 01이 이 값들을 왜 이렇게 정했는지(20자·10건·200건의 근거)는 01의 주석에
# 그대로 있다. 여기서 다시 논증하지 않는다 — 다시 논증하면 다시 정할 여지가
# 생기고, 그 여지가 바로 막으려는 것이다.
# ════════════════════════════════════════════════════════════════════════
MIN_CHARS = 20          # [01에서 가져옴] 정제 후 20자 미만 문서는 버린다
MIN_DOCS = 10           # [01에서 가져옴] 적격 문서가 10건 미만인 계정은 제외
MAX_DOCS = 200          # [01에서 가져옴] 계정당 최근 200건까지만 사용
LANG_TARGET = "en"      # [01에서 가져옴] 계정 단위 langid 판정이 이 언어여야 통과

# 자기폭로 문구 — 문서를 버리지 않고 그 문장만 도려낸다. [01에서 가져옴]
#
# fox8에서 이 정규식이 몇 건이나 걸리는지는 그 자체로 볼 만한 숫자다. fox8
# 봇은 ChatGPT에 탈취된 계정이므로 IRA(0에 가까워야 정상)와 달리 **걸리는
# 편이 정상**이다. 걸린 건수를 라벨별로 나누어 찍는다 — 봇 쪽에만 몰려 있다면
# 그것이 라벨링의 근거였을 수 있고, 그러면 우리가 재는 것이 문체가 아니라
# 라벨링 절차가 된다. [2/9]가 이 수를 라벨별로 낸다.
SELF_REVEAL = re.compile(
    r"(as an ai language model"
    r"|i'?m sorry,? but (i cannot|as an ai)"
    r"|i cannot (comply|fulfill|browse)"
    r"|openai'?s? (content )?polic)", re.I)

RE_SENT_SPLIT = re.compile(r"(?<=[.!?])\s+|\n+")      # [01에서 가져옴]
RE_URL = re.compile(r"(https?://\S+|www\.\S+)")       # [01에서 가져옴]
RE_MENTION = re.compile(r"@\w+")                      # [01에서 가져옴]
RE_WS = re.compile(r"\s+")                            # [01에서 가져옴]


# ════════════════════════════════════════════════════════════════════════
# [설정 2] fox8 고유 전처리 — 사전선언 12가 더하라고 한 것
# ────────────────────────────────────────────────────────────────────────
# (1) is_retweet == 0 인 행만 쓴다.
#     리트윗 텍스트는 그 계정이 쓴 글이 아니라 남의 글이다. 남기면 원저자의
#     문체가 그 계정의 문체로 계산된다.
#     ■ 이 규칙은 fox8에만 걸린다 ■ 레딧에는 리트윗 개념이 없어 BotSim 쪽에
#     짝이 되는 규칙이 아예 없다. 전처리 비대칭이며, 한계로 명시한다
#     (사전선언 12의 전처리 1이 그렇게 못 박았다). 11이 IRA에 건 것과 같은
#     성격의 비대칭이다.
#
# (2) 인용(is_quote)은 빼지 않는다.
#     인용 트윗은 남의 글을 붙이는 것이 아니라 남의 글에 **자기 말을 붙이는**
#     것이다. text 열에 담긴 것은 그 자기 말이다. 다만 인용 비율이 봇 2.1% ·
#     사람 11.8%로 어긋나 있으므로 그 사실을 [2/9]가 찍는다.
#
# (3) 답글(is_reply)도 빼지 않는다 — 주 분석에서는.
#     봇 49.2% · 사람 22.8%로 크게 어긋나 있어 10과 같은 성격의 장르 교란이
#     있다. 그래서 (가) 답글 비율을 계정 수준 공변량으로 기록하고,
#     (나) **답글 제외판을 보조 분석으로 함께 낸다**(사전선언 12 전처리 3).
#     보조판은 200건 절삭이 이미 걸린 문서의 부분집합이다 — 즉 "답글을 빼고
#     다시 최근 200건을 고른 것"이 아니라 "고른 200건에서 답글을 뺀 것"이다.
#     이 차이를 명시한다.
# ════════════════════════════════════════════════════════════════════════
