# ════════════════════════════════════════════════════════════════════════
# [산점도] ASCII 격자 — 어느 사분면에 몰리는가  [11에서 그대로 가져옴]
# ────────────────────────────────────────────────────────────────────────
# 12의 판정에서 ρ 하나보다 이 그림이 더 많은 것을 말한다. ρ는 "함께 움직이나"
# 만 말하고, 사분면은 "어느 쪽으로 함께 움직이나"를 말한다.
#
#       1사분면(둘 다 +)  BotSim 봇도 fox8 봇도 각자의 사람보다 많이 쓴다
#       3사분면(둘 다 −)  둘 다 각자의 사람보다 적게 쓴다
#         → 이 둘에 몰리면 전이. 방향이 옮겨 갔다는 뜻이다.
#       2·4사분면        한쪽만 사람과 다르다 → 방향이 뒤집힌 항목이다.
#
# ρ가 0에 가까워도 점이 1·3사분면에 몰려 있을 수 있고(부호는 같은데 크기
# 순서가 안 맞는 경우) 그 반대도 있다. 그래서 둘을 같이 본다.
# ════════════════════════════════════════════════════════════════════════
SCATTER_W = 25          # 가로 칸 수 (δ_BotSim, −1 … +1)
SCATTER_H = 15          # 세로 칸 수 (δ_fox8, +1 … −1)
SCATTER_LO, SCATTER_HI = -1.0, 1.0


def _cell(v, n_cells):
    """값 v(−1 … +1)를 0 … n_cells−1 칸으로 옮긴다. 범위를 벗어나면 끝 칸에 붙인다."""
    v = min(max(v, SCATTER_LO), SCATTER_HI)
    c = int(round((v - SCATTER_LO) / (SCATTER_HI - SCATTER_LO) * (n_cells - 1)))
    return min(max(c, 0), n_cells - 1)


def quadrant_counts(xs, ys):
    """
    사분면별 항목 수. x = δ_BotSim, y = δ_fox8. [11에서 가져옴]

    δ가 정확히 0인 항목은 어느 사분면에도 넣지 않고 '축 위'로 따로 센다.
    0을 한쪽 사분면에 몰아 넣으면 "그 단어를 아무도 안 썼다"는 사실이
    방향 주장으로 둔갑한다.
    """
    q = Counter()
    for x, y in zip(xs, ys):
        if x == 0.0 or y == 0.0:
            q["축 위 (δ = 0)"] += 1
        elif x > 0 and y > 0:
            q["1사분면 (둘 다 +)"] += 1
        elif x < 0 and y > 0:
            q["2사분면 (BotSim − · fox8 +)"] += 1
        elif x < 0 and y < 0:
            q["3사분면 (둘 다 −)"] += 1
        else:
            q["4사분면 (BotSim + · fox8 −)"] += 1
    return q


QUAD_NAMES = ("1사분면 (둘 다 +)", "3사분면 (둘 다 −)",
              "2사분면 (BotSim − · fox8 +)", "4사분면 (BotSim + · fox8 −)",
              "축 위 (δ = 0)")


def print_scatter(xs, ys, title):
    """
    δ_BotSim(가로) 대 δ_fox8(세로) 산점도를 ASCII로 그린다. [11에서 가져옴]

    사분면 경계선을 먼저 깔고 그 위에 점을 얹는다. 같은 칸에 여러 항목이
    겹치면 2~9는 숫자로, 10개 이상은 #으로 찍는다. 점 하나가 항목 하나이므로
    "몇 개가 어디에 있는가"가 눈으로 읽혀야 한다.
    """
    print(f"\n      {title}")
    if not xs:
        print("      그릴 점이 없습니다.")
        return Counter()

    grid = [[" "] * SCATTER_W for _ in range(SCATTER_H)]
    c0 = _cell(0.0, SCATTER_W)                      # δ_BotSim = 0 인 열
    r0 = (SCATTER_H - 1) - _cell(0.0, SCATTER_H)    # δ_fox8 = 0 인 행(위가 +1)
    for c in range(SCATTER_W):
        grid[r0][c] = "─"
    for r in range(SCATTER_H):
        grid[r][c0] = "│"
    grid[r0][c0] = "┼"

    counts = [[0] * SCATTER_W for _ in range(SCATTER_H)]
    for x, y in zip(xs, ys):
        c = _cell(x, SCATTER_W)
        r = (SCATTER_H - 1) - _cell(y, SCATTER_H)
        counts[r][c] += 1
    for r in range(SCATTER_H):
        for c in range(SCATTER_W):
            n = counts[r][c]
            if n == 0:
                continue
            grid[r][c] = "·" if n == 1 else (str(n) if n < 10 else "#")

    print(f"      세로 δ_fox8 · 가로 δ_BotSim · 격자 {SCATTER_W}×{SCATTER_H} · "
          f"점 {len(xs)}개")
    print("      한 칸에 2~9개면 그 숫자, 10개 이상이면 #.")
    print()
    for r, row in enumerate(grid):
        if r == 0:
            lab = "+1.0"
        elif r == r0:
            lab = " 0.0"
        elif r == SCATTER_H - 1:
            lab = "-1.0"
        else:
            lab = "    "
        print(f"      {lab} {''.join(row)}")

    axis = [" "] * SCATTER_W
    for text, center in (("-1.0", 1), ("0.0", c0), ("+1.0", SCATTER_W - 2)):
        start = max(0, min(SCATTER_W - len(text), center - len(text) // 2))
        for i, ch in enumerate(text):
            axis[start + i] = ch
    print("           " + "".join(axis))

    quad = quadrant_counts(xs, ys)
    total = sum(quad.values())
    print("\n        사분면별 항목 수")
    for name in QUAD_NAMES:
        n = quad.get(name, 0)
        print(f"          {lpad(name, 30)}{n:>5}  ({n / total:>5.1%})")
    same = quad.get("1사분면 (둘 다 +)", 0) + quad.get("3사분면 (둘 다 −)", 0)
    diff = (quad.get("2사분면 (BotSim − · fox8 +)", 0)
            + quad.get("4사분면 (BotSim + · fox8 −)", 0))
    print(f"          ── 같은 방향(1+3) {same} · 다른 방향(2+4) {diff}")
    return quad


# ════════════════════════════════════════════════════════════════════════
# [타이포그래피] 아포스트로피 정규화 — 곧은 것과 굽은 것  [04·11에서 가져옴]
# ════════════════════════════════════════════════════════════════════════
def normalize_apostrophe(s):
    """
    굽은 아포스트로피(’, U+2019)를 곧은 것(', U+0027)으로 바꾼다. [04에서 가져옴]

    04의 첫 전량 측정이 스스로 드러낸 문제다 — 's와 ’s가 따로 올라왔고,
    원문 아포스트로피의 37%가 굽은 쪽이었다. 방치하면 "누가 축약형을 덜
    쓴다"처럼 보이는 가짜 신호가 생긴다.

    12에서 이 정규화는 04보다 더 중요하다. 트위터 클라이언트(iOS는 굽은
    쪽을 자동으로 넣는다)와 레딧 입력창이 아포스트로피를 다르게 넣고,
    그러면 정규화를 빠뜨린 자리에서 **플랫폼 차이가 곧바로 δ로 둔갑한다.**
    더 나쁜 것은 fox8 안에서도 봇(API 게시)과 사람(앱 게시)의 클라이언트가
    다를 수 있다는 점이다 — 그때는 라벨과 정확히 겹치는 가짜 신호가 된다.
    토큰과 02 목록 양쪽에 같은 정규화를 건다. 잣대가 하나여야 한다.
    """
    return s.replace("’", "'")


# ════════════════════════════════════════════════════════════════════════
# [1] fox8 코퍼스 — 01의 규칙을 그대로, 리트윗 제외만 앞에 붙인다
# ════════════════════════════════════════════════════════════════════════
def clean_doc(text):
    """
    글 1건을 정제한다. [01에서 한 글자도 고치지 않고 가져옴 · 11을 경유]

    통과하면 (정제 문자열, None, 절제여부), 탈락하면 (None, 사유, 절제여부).

    순서가 중요하다.
      1) 자기폭로 문장 절제 — 남은 문장으로 계속 진행
      2) URL·멘션 제거
      3) 길이 검사 — 절제 뒤의 길이로 판정해야 정확하다
    URL을 먼저 지우고 길이를 재야, 링크만 잔뜩 붙은 짧은 글이 '긴 글'로
    위장되지 않는다.

    ■ fox8에서 이 순서가 특히 크게 작동한다 ■
    트윗은 t.co 단축 링크를 본문에 그대로 달고 다닌다("https://t.co/xxxxxxxxxx"
    가 23자다). 링크를 지우기 전에 길이를 재면 링크만 붙은 한 마디짜리 트윗이
    20자 문턱을 넘어 들어온다. 멘션도 마찬가지다 — 답글은 본문 앞에
    "@아무개"가 줄줄이 붙는데, fox8은 답글 비율이 봇 49.2% · 사람 22.8%로
    어긋나 있어 멘션을 지우지 않으면 그 어긋남이 곧바로 길이 필터의
    비대칭으로 이어진다. RE_MENTION 이 그것을 지운다.
    """
    if not text:
        return None, "빈 문자열", False
    t = unicodedata.normalize("NFC", str(text))

    # (1) 자기폭로 문장만 도려내기
    excised = False
    if SELF_REVEAL.search(t):
        sents = RE_SENT_SPLIT.split(t)
        kept = [s for s in sents if s.strip() and not SELF_REVEAL.search(s)]
        t = " ".join(kept)
        excised = True
        if not t.strip():
            return None, "자기폭로 절제 후 내용 없음", True

    # (2) 링크·멘션 제거 — 문체가 아니라 행동의 흔적
    t = RE_URL.sub(" ", t)
    t = RE_MENTION.sub(" ", t)
    t = RE_WS.sub(" ", t).strip()

    # (3) 길이 검사
    if len(t) < MIN_CHARS:
        reason = ("자기폭로 절제 후 " if excised else "") + f"{MIN_CHARS}자 미만"
        return None, reason, excised
    return t, None, excised


def year_of(created_at):
    """
    created_at 에서 연도 네 글자를 꺼낸다.

    이 자료의 형식은 "2018-04-18 14:09:01" 이라 앞 네 글자가 곧 연도다
    (2026-08-27 직접 확인). 네 글자가 숫자가 아니면 "?" 로 적는다 — 추측해
    채워 넣으면 완화 A가 엉뚱한 문서를 고르게 된다.
    """
    s = (created_at or "")[:4]
    return s if len(s) == 4 and s.isdigit() else "?"


def bucket_key(year, is_reply):
    """
    한 문서를 어느 버킷에 담을지 정한다.  "연도|답글여부" 꼴이다.

    ■ 왜 버킷인가 ■
    04는 계정 하나를 통째로 세어 카운트 한 벌을 냈다. 12는 같은 계정에서
    '2019~2020년 문서만'(완화 A) · '2023년 문서만'(완화 B의 후) · '답글이
    아닌 문서만'(보조 분석)을 각각 다시 세어야 한다. 문서를 다시 파싱하면
    한 시간이 세 번 든다.

    그래서 파싱은 한 번만 하고, 세는 자리에서 문서를 버킷에 나눠 담는다.
    나중에 필요한 버킷만 골라 더하면 그것이 곧 그 부분집합의 카운트다.
    덧셈은 결합법칙을 따르므로 "버킷을 다 더한 것"과 "통째로 센 것"은 정확히
    같다 — [4/9]가 그 항등식을 실제로 검산한다.
    """
    return f"{year}|{1 if is_reply else 0}"


def bucket_year(key):
    """버킷 이름에서 연도만."""
    return key.split("|", 1)[0]


def bucket_is_reply(key):
    """버킷 이름에서 답글 여부만."""
    return key.rsplit("|", 1)[-1] == "1"


def empty_counts():
    """04와 같은 꼴의 빈 카운트 한 벌."""
    return {"문서수": 0, "문장수": 0, "토큰수": 0, "토큰수_구두점제외": 0,
            "기능어": {}, "UPOS": {}, "자질": {}}


def merge_buckets(buckets, pick=None):
    """
    버킷 여럿을 04 꼴의 카운트 한 벌로 합친다.

    pick — 버킷 이름을 받아 참/거짓을 돌려주는 함수. None이면 전부 더한다.
    반환은 04의 계정 한 칸과 완전히 같은 모양이라, 뒤의 compute_rates ·
    compute_ratios · compute_upos_ratios 가 04의 자료를 다룰 때와 한 글자도
    다르지 않게 동작한다. 부분집합 분석마다 계산 코드를 새로 쓰지 않는
    것이 요점이다 — 새로 쓰면 그 사본이 언젠가 본체와 갈라진다.
    """
    out = empty_counts()
    for key, c in buckets.items():
        if pick is not None and not pick(key):
            continue
        out["문서수"] += c["문서수"]
        out["문장수"] += c["문장수"]
        out["토큰수"] += c["토큰수"]
        out["토큰수_구두점제외"] += c["토큰수_구두점제외"]
        for field in ("기능어", "UPOS", "자질"):
            dst = out[field]
            for k, n in c[field].items():
                dst[k] = dst.get(k, 0) + n
    return out


def subset_measures(measures, uids, pick=None):
    """
    계정별로 원하는 버킷만 합쳐 '04 꼴 측정치 사전'을 만든다.

    이 한 함수가 12의 부분집합 분석 전부를 떠받친다.
        주 비교      pick = None                        (전부)
        완화 A       pick = 연도가 2019 또는 2020        (사람만)
        완화 B 후    pick = 연도가 2023                  (봇만)
        보조 분석    pick = 답글이 아님                  (양쪽)
    돌려받은 사전은 04의 "계정" 블록과 모양이 같으므로 뒤의 모든 계산 코드가
    그대로 돌아간다.

    문서가 하나도 없는 계정(그 부분집합에 해당 문서가 없는 계정)은 빼고
    돌려준다. 남겨 두면 분모가 0이 되어 '분모 0 계정'으로 세어지는데, 그것은
    나눗셈 불성립이 아니라 애초에 표본에 없는 계정이다. 둘을 섞으면 안 된다.
    """
    out = {}
    for uid in uids:
        rec = measures.get(uid)
        if not rec:
            continue
        merged = merge_buckets(rec["연도별"], pick)
        if merged["문서수"] > 0:
            out[uid] = merged
    return out


def db_overview(conn):
    """
    users·tweets 를 훑어 실태표를 다시 만든다. [1/9]가 사전선언의 표와 대조한다.

    왜 다시 세나 — 사전선언 12의 실태표는 2026-08-27에 손으로 조회한 값이다.
    그 조회가 다른 파일을 봤거나 다른 조건을 썼다면 12의 전제("봇 1,140 ·
    사람 1,139 · 답글 49.2% 대 22.8%")가 근거를 잃는데, 화면에는 아무 이상도
    안 찍힌다. 어긋나도 중단하지 않는다 — 12의 계산은 표가 아니라 자료로
    하기 때문이다. 다만 어긋난 사실은 남는다.
    """
    cur = conn.cursor()
    ov = {}
    ov["users_행수"] = cur.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    ov["tweets_행수"] = cur.execute("SELECT COUNT(*) FROM tweets").fetchone()[0]

    ov["계정_라벨별"] = {}
    ov["계정_출처별"] = {}
    for lab, ds, n in cur.execute(
            "SELECT label, dataset, COUNT(*) FROM users "
            "GROUP BY label, dataset").fetchall():
        ov["계정_라벨별"][lab] = ov["계정_라벨별"].get(lab, 0) + n
        ov["계정_출처별"][ds] = n

    ov["트윗_라벨별"] = {}
    ov["비율_라벨별"] = {}
    for lab, n, rt, rp, qt in cur.execute(
            "SELECT label, COUNT(*), SUM(is_retweet), SUM(is_reply), "
            "SUM(is_quote) FROM tweets GROUP BY label").fetchall():
        ov["트윗_라벨별"][lab] = n
        ov["비율_라벨별"][lab] = {
            "리트윗": (rt or 0) / n if n else None,
            "답글": (rp or 0) / n if n else None,
            "인용": (qt or 0) / n if n else None,
        }

    ov["비리트윗_라벨별"] = {}
    for lab, n in cur.execute(
            "SELECT label, COUNT(*) FROM tweets WHERE is_retweet = 0 "
            "GROUP BY label").fetchall():
        ov["비리트윗_라벨별"][lab] = n

    # 연도별 비리트윗 — 시기 교란의 크기를 눈으로 보는 자리다.
    ov["비리트윗_연도별"] = {}
    for lab, yr, n in cur.execute(
            "SELECT label, substr(created_at,1,4), COUNT(*) FROM tweets "
            "WHERE is_retweet = 0 GROUP BY label, substr(created_at,1,4)"
    ).fetchall():
        ov["비리트윗_연도별"].setdefault(lab, {})[yr or "?"] = n
    return ov


def print_db_overview(ov):
    """실태표를 사전선언 12의 값과 나란히 찍는다. 어긋난 칸 목록을 돌려준다."""
    bad = []

    def cmp(name, got, want, fmt="{:,}"):
        mark = ""
        if want is not None and got != want:
            bad.append(f"{name}: 다시 셈 {got} ≠ 사전선언 {want}")
            mark = "   ← 어긋남"
        w = "—" if want is None else fmt.format(want)
        print(f"        {lpad(name, 28)}{fmt.format(got):>12}"
              f"   (사전선언 {w}){mark}")

    print("\n      ── sqlite 실태 재집계 (사전선언 12의 표와 대조) ──")
    cmp("users 행", ov["users_행수"], EXPECT_USERS)
    cmp("tweets 행", ov["tweets_행수"], EXPECT_TWEETS)
    for lab in (FOX8_BOT_LABEL, FOX8_HUMAN_LABEL):
        cmp(f"계정 · {lab}", ov["계정_라벨별"].get(lab, 0),
            EXPECT_ACCOUNTS.get(lab))
        cmp(f"트윗 · {lab}", ov["트윗_라벨별"].get(lab, 0),
            EXPECT_TWEETS_BY_LABEL.get(lab))
        cmp(f"비리트윗 · {lab}", ov["비리트윗_라벨별"].get(lab, 0),
            EXPECT_NONRT.get(lab))

    # 봇은 전부 dataset = 'fox8' 이어야 한다(사전선언 12의 실태표). 아니면
    # 출처 4분할의 전제가 무너진다 — 나뉘는 것은 대조군 쪽뿐이라는 전제다.
    if FOX8_BOT_SOURCE not in ov["계정_출처별"]:
        bad.append(f"봇 출처 '{FOX8_BOT_SOURCE}' 가 users.dataset 에 없다")
    print("\n      출처(users.dataset)별 계정")
    for ds, n in sorted(ov["계정_출처별"].items(), key=lambda kv: -kv[1]):
        want = EXPECT_SOURCES.get(ds)
        note = "" if want is None else f"   (사전선언 {want:,})"
        if want is not None and n != want:
            bad.append(f"출처 {ds}: 다시 셈 {n:,} ≠ 사전선언 {want:,}")
            note += "  ← 어긋남"
        role = " (봇)" if ds == FOX8_BOT_SOURCE else " (사람)"
        print(f"        {ds:<22}{n:>8,}{role}{note}")

    print("\n      트윗 종류 비율 (전체 트윗 대비)")
    print("        라벨      리트윗      답글      인용")
    for lab in (FOX8_BOT_LABEL, FOX8_HUMAN_LABEL):
        r = ov["비율_라벨별"].get(lab) or {}
        print(f"        {lab:<8}{(r.get('리트윗') or 0):>8.1%}"
              f"{(r.get('답글') or 0):>10.1%}{(r.get('인용') or 0):>10.1%}")
    for lab, table, name in ((FOX8_BOT_LABEL, EXPECT_RT_RATE, "리트윗"),
                             (FOX8_HUMAN_LABEL, EXPECT_RT_RATE, "리트윗"),
                             (FOX8_BOT_LABEL, EXPECT_REPLY_RATE, "답글"),
                             (FOX8_HUMAN_LABEL, EXPECT_REPLY_RATE, "답글"),
                             (FOX8_BOT_LABEL, EXPECT_QUOTE_RATE, "인용"),
                             (FOX8_HUMAN_LABEL, EXPECT_QUOTE_RATE, "인용")):
        got = (ov["비율_라벨별"].get(lab) or {}).get(name)
        want = table.get(lab)
        if got is not None and want is not None and abs(got - want) > 0.002:
            bad.append(f"{name} 비율 · {lab}: 다시 셈 {got:.1%} ≠ "
                       f"사전선언 {want:.1%}")
    print(f"        (사전선언 — 리트윗 봇 {EXPECT_RT_RATE['bot']:.1%} · "
          f"사람 {EXPECT_RT_RATE['human']:.1%} / 답글 "
          f"봇 {EXPECT_REPLY_RATE['bot']:.1%} · "
          f"사람 {EXPECT_REPLY_RATE['human']:.1%} /")
    print(f"         인용 봇 {EXPECT_QUOTE_RATE['bot']:.1%} · "
          f"사람 {EXPECT_QUOTE_RATE['human']:.1%})")
    print("        ■ 답글이 봇 쪽에 두 배 넘게 몰려 있다. 10이 다룬 것과 같은")
    print("          성격의 장르 교란이다 — [5/9]가 답글 제외판을 보조로 낸다.")

    print("\n      비리트윗의 연도 분포 (상위 6개)")
    for lab in (FOX8_BOT_LABEL, FOX8_HUMAN_LABEL):
        years = ov["비리트윗_연도별"].get(lab) or {}
        tot = sum(years.values()) or 1
        top = sorted(years.items(), key=lambda kv: -kv[1])[:6]
        print(f"        {lab:<8}"
              + " · ".join(f"{y} {n:,}({n/tot:.1%})" for y, n in top))
    print(f"        (사전선언 — 봇 {POST_YEAR}년 "
          f"{EXPECT_BOT_2023_NONRT:,} · 사람 "
          + " · ".join(f"{y}년 {n:,}"
                       for y, n in sorted(EXPECT_HUMAN_TOP_YEARS.items(),
                                          key=lambda kv: -kv[1])) + ")")
    for yr, want in EXPECT_HUMAN_TOP_YEARS.items():
        got = (ov["비리트윗_연도별"].get(FOX8_HUMAN_LABEL) or {}).get(yr, 0)
        if got != want:
            bad.append(f"사람 {yr}년 비리트윗: 다시 셈 {got:,} ≠ "
                       f"사전선언 {want:,}")
    bot_2023 = (ov["비리트윗_연도별"].get(FOX8_BOT_LABEL) or {}).get(POST_YEAR, 0)
    if bot_2023 != EXPECT_BOT_2023_NONRT:
        bad.append(f"봇 {POST_YEAR}년 비리트윗: 다시 셈 {bot_2023:,} ≠ "
                   f"사전선언 {EXPECT_BOT_2023_NONRT:,}")
    print()
    print("      ■ 여기가 12의 가장 무거운 한계다 ■ 봇은 2023년에, 사람은")
    print("        2017~2020년에 몰려 있다. 봉인 라인 치명 1이 잰 대로 이")
    print(f"        자료는 **연도만으로 AUC {SEALED_YEAR_AUC:.3f}** 이다. 문체를 한")
    print("        글자도 보지 않고 날짜만 보고도 라벨을 다 맞힌다는 뜻이다.")
    print("        [7/9]·[8/9]의 완화 둘은 이것을 줄이려는 것이지 없애는 것이")
    print("        아니다. 없앨 수 있다고 쓰지 않는다.")
    return bad


def build_fox8_corpus(conn):
    """
    tweets 를 스트리밍으로 읽어 계정별 문서를 모으고 01의 필터를 건다.

    ■ 왜 스트리밍인가 ■
    비리트윗만 해도 23만 행이고 본문이 붙어 있다. 통째로 리스트에 담으면
    정제 전 원문까지 메모리에 올라간다. sqlite3 커서는 행을 하나씩 흘려
    주므로, 읽는 즉시 걸러 통과한 것만 남기면 원문은 쌓이지 않는다.

    ■ 계정당 200건을 힙으로 유지하는 이유 ■ [11에서 가져옴]
    01은 계정의 글을 전부 모아 정렬한 뒤 뒤에서 200건을 잘랐다. 여기서 같은
    짓을 하면 통과 문서 18만여 건이 한꺼번에 메모리에 앉는다. 대신 계정마다
    크기 200짜리 최소 힙을 유지하고, 200을 넘으면 가장 작은(= 가장 오래된)
    것을 밀어낸다. 결과는 정렬 후 뒤 200건과 **정확히 같다** — 정렬키에
    등장 순번(seq)을 붙여 두었기 때문이다. 같은 시각의 행이 여럿이어도
    순번이 유일해 순서가 결정되고, 그 순서는 01의 안정 정렬이 매기던 순서와
    같다.

    ■ 시각을 못 읽은 행 ■ [11의 parse_publish 주석과 같은 판단]
    created_at 앞 네 글자가 숫자가 아니면 정렬키의 첫 칸에 1을 넣어 맨 뒤로
    보낸다. 앞으로 보내면 '가장 오래된 글' 취급이 되어 200건 절삭에서 먼저
    버려지는데, 시각을 못 읽었다는 사실은 그 글의 내용에 대해 아무것도 말해
    주지 않는다. 그런 글이 조용히 표본에서 사라지는 쪽이 더 나쁘다.

    필터 순서 — 사전선언 12가 적은 그대로다.
        is_retweet == 0  →  01의 정제  →  MIN_CHARS
        →  계정별 시간순 MAX_DOCS 절삭  →  MIN_DOCS  →  계정 단위 langid
    (자기폭로 절제는 01의 clean_doc 안에서 정제의 첫 단계로 일어난다.)

    반환: (코퍼스, 깔때기, 계정메타, 언어판정)
        코퍼스   {uid: [(정제문서, 버킷이름), ...]}   ← uid에 접두사 없음
        계정메타 {uid: {라벨, 출처, 답글비율, 연도분포, 문서수}}
    """
    import langid

    cur = conn.cursor()
    # 라벨·출처는 users 에서 미리 받아 둔다. tweets 에도 label 이 있지만 두
    # 곳을 다 믿으면 어긋났을 때 어느 쪽을 쓴 것인지 알 수 없게 된다.
    user_label, user_source = {}, {}
    for uid, lab, ds in cur.execute(
            "SELECT user_id, label, dataset FROM users").fetchall():
        user_label[uid] = lab
        user_source[uid] = ds

    drop = Counter()                 # 사유별 행 탈락
    drop_by_label = {}               # 라벨별 탈락 (출처별 생존율의 재료)
    heaps = {}                       # uid -> [(못읽음, created_at, seq, 문서, 버킷)]
    n_rows = 0
    n_trimmed = 0
    n_excised = Counter()            # 라벨별 자기폭로 절제 문서
    n_excised_kept = Counter()
    n_time_bad = 0
    seq = 0

    t0 = time.time()
    for uid, created, text, is_reply in cur.execute(
            "SELECT user_id, created_at, text, is_reply FROM tweets "
            "WHERE is_retweet = 0"):
        n_rows += 1
        lab = user_label.get(uid, "?")
        if not uid:
            drop["작성자 없음"] += 1
            continue

        cleaned, reason, excised = clean_doc(text)
        if excised:
            n_excised[lab] += 1
        if cleaned is None:
            drop[reason] += 1
            drop_by_label.setdefault(reason, Counter())[lab] += 1
            continue
        if excised:
            n_excised_kept[lab] += 1

        yr = year_of(created)
        if yr == "?":
            n_time_bad += 1
        bad_time = 1 if yr == "?" else 0
        item = (bad_time, created or "", seq, cleaned,
                bucket_key(yr, is_reply))
        seq += 1
        h = heaps.setdefault(uid, [])
        if len(h) < MAX_DOCS:
            heapq.heappush(h, item)
        else:
            heapq.heappushpop(h, item)      # 가장 오래된 것을 밀어낸다
            n_trimmed += 1
    print(f"      비리트윗 {n_rows:,}행 훑기 {time.time() - t0:.1f}초 · "
          f"통과 문서를 가진 계정 {len(heaps):,}개")

    # ── 계정별로 시간순 복원 + MIN_DOCS ─────────────────────────
    candidates, short_by_label = {}, Counter()
    for uid in sorted(heaps):
        items = sorted(heaps[uid])
        docs = [(c, k) for _, _, _, c, k in items]
        if len(docs) >= MIN_DOCS:
            candidates[uid] = docs
        else:
            short_by_label[user_label.get(uid, "?")] += 1
    heaps.clear()

    # ── 계정 단위 언어 판정 (01의 3-2와 같음) ───────────────────
    # ■ 이 관문이 12에서 특히 중요하다 ■ fox8 사람 계정은 네 연구에서 왔고
    # 그중 gilani-17 은 비영어 계정을 많이 담고 있는 것으로 알려져 있다.
    # 계정 단위 영어 판정을 걸면 출처마다 생존율이 크게 달라질 수 있고,
    # 그러면 '사람'이라는 무더기의 구성 자체가 바뀐다. 사전선언 12 판정 4가
    # "출처별 생존율이 크게 달라지면 그 사실도 보고한다"고 적은 이유다.
    print(f"      계정 {len(candidates):,}개 언어 판정 중...", end=" ", flush=True)
    t0 = time.time()
    accounts, lang_info = {}, {}
    lang_counter = Counter()
    lang_dropped = Counter()          # 출처별 비영어 탈락
    for uid in sorted(candidates):
        docs = candidates[uid]
        joined = " ".join(c for c, _ in docs)
        lang, score = langid.classify(joined)
        lang_info[uid] = {"lang": lang, "score": round(float(score), 1),
                          "chars": len(joined)}
        lang_counter[lang] += 1
        if lang == LANG_TARGET:
            accounts[uid] = docs
        else:
            lang_dropped[user_source.get(uid, "?")] += 1
    print(f"{time.time() - t0:.1f}초")

    # ── 계정 메타 — 답글 비율은 계정 수준 공변량이다 ────────────
    meta = {}
    for uid, docs in accounts.items():
        n_reply = sum(1 for _, k in docs if bucket_is_reply(k))
        years = Counter(bucket_year(k) for _, k in docs)
        meta[uid] = {
            "라벨": user_label.get(uid, "?"),
            "출처": user_source.get(uid, "?"),
            "문서수": len(docs),
            "답글수": n_reply,
            "답글비율": round(n_reply / len(docs), RATE_DIGITS),
            "연도분포": dict(sorted(years.items())),
        }

    # ── 출처별 생존율 ───────────────────────────────────────────
    src_total = Counter(user_source.values())
    src_alive = Counter(m["출처"] for m in meta.values())
    survival = {}
    for src, tot in sorted(src_total.items(), key=lambda kv: -kv[1]):
        alive = src_alive.get(src, 0)
        survival[src] = {
            "원본계정": tot,
            "적격계정": alive,
            "생존율": round(alive / tot, 4) if tot else None,
            "비영어탈락": lang_dropped.get(src, 0),
        }

    funnel = {
        "비리트윗_행수": n_rows,
        "행_탈락사유": dict(drop.most_common()),
        "행_탈락사유_라벨별": {r: dict(c) for r, c in drop_by_label.items()},
        "상한초과_절삭문서수": n_trimmed,
        "자기폭로_절제문서수": dict(n_excised),
        "자기폭로_절제후_생존문서수": dict(n_excised_kept),
        "시각파싱_실패문서수": n_time_bad,
        "문서1건이상_계정수": len(candidates) + sum(short_by_label.values()),
        "문서부족_탈락계정_라벨별": dict(short_by_label),
        "언어판정_대상계정수": len(candidates),
        "언어별_계정수": dict(lang_counter.most_common()),
        "비영어_탈락계정_출처별": dict(lang_dropped),
        "적격_계정수": len(accounts),
        "적격_문서수": sum(len(v) for v in accounts.values()),
        "적격_라벨별": dict(Counter(m["라벨"] for m in meta.values())),
        "출처별_생존": survival,
    }
    return accounts, funnel, meta, lang_info


def build_pre_corpus(conn, bot_uids):
    """
    탈취 전(≤2022) 봇 텍스트로 두 번째 코퍼스를 짓는다. 완화 B의 '전' 쪽이다.

    같은 01 규칙을 걸고 MIN_DOCS 도 10으로 유지한다(사전선언 12). MAX_DOCS
    200 도 그대로 걸지만 계정당 최대가 109건이라 실제로는 한 번도 걸리지
    않는다 — 그래도 규칙을 빼지 않는 것은 "이쪽만 다른 규칙을 썼다"는 칸을
    남기지 않기 위해서다.

    ■ 계정 단위 langid 를 여기에도 거는가 ■ 건다. 01 규칙 그대로이기도 하고,
    무엇보다 전 텍스트가 영어가 아닌 계정을 남기면 '전 대 후'의 차이에
    **언어가 바뀐 몫**이 통째로 섞인다(2018년 독일어 트윗 대 2023년 영어
    트윗). 그것은 탈취의 효과도 세월의 효과도 아니다. 몇 계정이 이 관문에서
    빠졌는지는 깔때기에 남긴다.

    반환: (코퍼스, 깔때기). 코퍼스의 uid 에는 접두사가 없다.
    """
    import langid

    cur = conn.cursor()
    heaps, drop = {}, Counter()
    n_rows = 0
    seq = 0
    raw_count = Counter()      # 정제 전 계정별 행 수 — 사전선언의 44/1,591과 대조

    for uid, created, text, is_reply in cur.execute(
            "SELECT user_id, created_at, text, is_reply FROM tweets "
            "WHERE is_retweet = 0 AND label = ? "
            "AND substr(created_at,1,4) <= ?",
            (FOX8_BOT_LABEL, PRE_YEAR_MAX)):
        n_rows += 1
        raw_count[uid] += 1
        cleaned, reason, _ = clean_doc(text)
        if cleaned is None:
            drop[reason] += 1
            continue
        yr = year_of(created)
        item = (1 if yr == "?" else 0, created or "", seq, cleaned,
                bucket_key(yr, is_reply))
        seq += 1
        h = heaps.setdefault(uid, [])
        if len(h) < MAX_DOCS:
            heapq.heappush(h, item)
        else:
            heapq.heappushpop(h, item)

    # 사전선언이 센 것은 '정제 전' 기준이다. 그 기준으로도 다시 세어 나란히 둔다.
    raw_ok = {u: n for u, n in raw_count.items() if n >= MIN_DOCS}

    candidates, short = {}, 0
    for uid in sorted(heaps):
        items = sorted(heaps[uid])
        docs = [(c, k) for _, _, _, c, k in items]
        if len(docs) >= MIN_DOCS:
            candidates[uid] = docs
        else:
            short += 1

    accounts, lang_dropped = {}, 0
    for uid in sorted(candidates):
        docs = candidates[uid]
        lang, _ = langid.classify(" ".join(c for c, _ in docs))
        if lang == LANG_TARGET:
            accounts[uid] = docs
        else:
            lang_dropped += 1

    # 본 코퍼스(후)에 없는 계정은 쌍이 성립하지 않는다. 여기서 미리 뺀다.
    not_in_post = sorted(set(accounts) - set(bot_uids))
    for uid in not_in_post:
        del accounts[uid]

    funnel = {
        "정제전_행수": n_rows,
        "정제전_10건이상_계정수": len(raw_ok),
        "정제전_10건이상_문서수": sum(raw_ok.values()),
        "행_탈락사유": dict(drop.most_common()),
        "정제후_10건이상_계정수": len(candidates),
        "문서부족_탈락계정수": short,
        "비영어_탈락계정수": lang_dropped,
        "본코퍼스에_없어_제외": len(not_in_post),
        "본코퍼스에_없어_제외_목록": not_in_post,
        "최종_계정수": len(accounts),
        "최종_문서수": sum(len(v) for v in accounts.values()),
        "사전선언_추정": {"계정": EXPECT_PRE_ACCOUNTS, "문서": EXPECT_PRE_DOCS},
    }
    return accounts, funnel


# ════════════════════════════════════════════════════════════════════════
# [2] 파이프라인과 측정 — 04와 똑같이, 다만 버킷에 나눠 담는다
# ════════════════════════════════════════════════════════════════════════
def build_pipeline():
    """
    04가 만든 그 파이프라인을 그대로 만든다. [04에서 가져옴]

        processors="tokenize,pos" · use_gpu=False

    한 글자라도 다르게 만들면 03의 감사 결과가 이 측정에 적용되지 않고,
    무엇보다 12의 수치를 04의 수치와 나란히 놓을 수 없게 된다 — 두 표의
    차이에 '자료가 다른 몫'과 '파서 구성이 달라진 몫'이 섞이기 때문이다.
    12가 재려는 것은 앞의 하나뿐이다.

    stanza.download를 부르지 않는다. 03이 이미 모델을 ~/stanza_resources에
    받아 두었고, download는 매번 인터넷으로 목록 파일을 확인하러 나간다.
    """
    import stanza
    print("      파이프라인 생성 중...", end=" ", flush=True)
    t0 = time.time()
    nlp = stanza.Pipeline(lang="en", processors="tokenize,pos",
                          verbose=False, use_gpu=False)
    print(f"{time.time() - t0:.1f}초")
    return nlp


def measure_account(nlp, docs, keys, funcword_set):
    """
    한 계정의 문서 전부를 파싱해 **버킷별** 원카운트를 만든다. [04에서 가져옴 + 버킷]

    ── bulk 처리로 파싱한다 ────────────────────────────────────────
    문서를 하나씩 nlp(text)로 넘기면 03 실측 173 ms/문서다. bulk_process는
    문서 목록을 받아 내부에서 묶어 처리하므로 호출 비용이 분산된다(04 실측
    25 ms/문서). 문서 경계는 보존된다 — 입력 N건에 Document도 N개다.
    **버킷 나누기가 이 효율을 건드리지 않는다**: 파싱은 계정 전체를 한 번에
    하고, 나누는 것은 다 센 뒤 카운터에 담을 때뿐이다.

    ── 기능어는 '표면형'으로 센다 ──────────────────────────────────
    소문자로 바꾸고 아포스트로피를 정규화한 표면형이 02의 목록(같은 정규화
    적용, 172종)에 있으면 센다. 그 자리에서 파서가 붙인 품사는 보지 않는다.
    품사를 조건으로 걸면 파서 오류율의 자료 간 차이가 측정치에 그대로
    들어오는데, 03 [D]가 걱정한 것이 정확히 그것이었다. 트위터 텍스트는
    레딧보다 파서에게 낯설어 이 걱정이 12에서 더 크다.

    ── 원카운트만 저장한다 ────────────────────────────────────────
    사용률(= 횟수 / 총 토큰)은 [5/9]에서 05의 분모 규칙으로 계산한다.
    반환값의 카운트는 0을 담지 않는다(희소 저장). 없는 키 = 0으로 읽으면 된다.

    반환: {"연도별": {버킷이름: 04 꼴 카운트}}
    """
    parsed = nlp.bulk_process(docs)
    buckets = {}

    for doc, key in zip(parsed, keys):
        b = buckets.get(key)
        if b is None:
            b = buckets[key] = empty_counts()
        b["문서수"] += 1
        fw, upos, feats = b["기능어"], b["UPOS"], b["자질"]
        for sent in doc.sentences:
            b["문장수"] += 1
            for w in sent.words:
                b["토큰수"] += 1
                upos[w.upos] = upos.get(w.upos, 0) + 1
                if w.upos != "PUNCT":
                    b["토큰수_구두점제외"] += 1

                surface = normalize_apostrophe(w.text.lower())
                if surface in funcword_set:
                    fw[surface] = fw.get(surface, 0) + 1

                # feats는 "Mood=Ind|Number=Sing|Tense=Pres" 처럼 막대로 이어진
                # 문자열이다. 막대로 끊어 "키=값" 단위로 센다. 통짜로 세면
                # 조합이 수백 가지로 흩어져 아무것도 비교할 수 없다.
                if w.feats:
                    for kv in w.feats.split("|"):
                        feats[kv] = feats.get(kv, 0) + 1

    return {"연도별": buckets}


def input_fingerprint(corpus, pre_corpus, funcwords):
    """
    입력이 무엇이었는지 짧게 요약한 지문을 만든다. [04·11에서 가져옴]

    쓸모: 중간 저장 파일을 이어받을 때 "그때의 입력과 지금의 입력이 같은가"를
    확인한다. 코퍼스 구축 코드를 한 줄 고쳐 계정 수가 달라졌는데 앞의 900계정
    결과를 그대로 이어 붙이면, 한 파일 안에 기준이 다른 수치가 섞인다.
    눈으로는 절대 못 잡는 종류의 오염이다.

    12는 코퍼스가 둘이므로 둘 다 지문에 넣는다. 전 텍스트 코퍼스만 달라진
    경우에도 이어받기를 막아야 한다 — 완화 B의 짝이 어긋나기 때문이다.
    """
    h = hashlib.sha256("\n".join(funcwords).encode("utf-8")).hexdigest()[:16]
    return {
        "코퍼스": f"fox8 트윗(is_retweet=0) + 탈취전(≤{PRE_YEAR_MAX}) 봇 텍스트",
        "기능어_해시": h,
        "기능어_개수": len(funcwords),
        "정규화": "아포스트로피 U+2019→U+0027",   # 세는 규칙도 지문의 일부다
        "본_계정수": len(corpus),
        "본_문서수": sum(len(v) for v in corpus.values()),
        "전_계정수": len(pre_corpus),
        "전_문서수": sum(len(v) for v in pre_corpus.values()),
    }


def self_check_contraction(nlp, funcword_set):
    """
    02의 목록과 stanza의 토큰화가 서로 맞물리는지 확인한다. [04에서 가져옴]

    왜 매 실행마다 보나. 02 목록은 UD 분해형 규약을 따른다 — 목록에 don't가
    아니라 do와 n't가 따로 들어 있다. 이 규약은 stanza가 실제로 축약형을
    쪼개 줄 때만 맞는다. 쪼개지 않게 되면(모델 교체, 버전 변경, 파이프라인
    구성 실수) don't는 목록의 어느 항목과도 일치하지 않아 조용히 0으로
    세어진다. 오류 메시지는 나오지 않는다. 부정 표현이 통째로 사라진 표를
    가지고 한 시간을 돌린 뒤에야 알게 된다.

    검사는 본 측정과 똑같은 함수(measure_account)를 부른다. 검사만 통과하고
    본 측정은 다른 경로로 가는 일이 없게 하려는 것이다. 버킷 이름은 아무
    값이나 되며, 여기서는 두 문장을 한 버킷에 담아 합계를 본다.
    """
    print("\n  ── (2) 축약형이 기능어로 잡히는가 — 곧은 것과 굽은 것 모두 ──")
    print(f'  입력 1 (곧은 \'): "{SELF_CHECK_TEXT}"')
    print(f'  입력 2 (굽은 ’): "{SELF_CHECK_TEXT_CURLY}"')
    print("  03 [C] 문장과 그 굽은 아포스트로피판이다. 분해(do+n't)와")
    print("  정규화(’→')가 함께 작동해야 아래 기대값이 나온다.")

    docs = [SELF_CHECK_TEXT, SELF_CHECK_TEXT_CURLY]
    got = measure_account(nlp, docs, ["검사|0", "검사|0"], funcword_set)
    counts = merge_buckets(got["연도별"])["기능어"]

    ok = True
    for word, expect in SELF_CHECK_EXPECT.items():
        actual = counts.get(word, 0)
        mark = "통과" if actual == expect else "실패"
        if actual != expect:
            ok = False
        print(f"  {word:<6} 기대 {expect}회 · 실제 {actual}회   {mark}")
    print(f"  (이 문장에서 잡힌 기능어 전체: {counts})")

    # 버킷 나누기가 합계를 바꾸지 않는가 — 결합법칙 검산.
    split = measure_account(nlp, docs, ["A|0", "B|1"], funcword_set)
    merged = merge_buckets(split["연도별"])
    same = (merged["기능어"] == counts
            and merged["토큰수"] == merge_buckets(got["연도별"])["토큰수"])
    ok = ok and same
    print(f"  버킷 결합법칙  같은 두 문장을 한 버킷 대 두 버킷으로 담아 합계 "
          f"비교 → {'통과' if same else '실패'}")
    print("  (버킷을 다 더한 것과 통째로 센 것이 같아야 [7/9]·[8/9]의 부분집합")
    print("   분석이 성립한다. 다르면 measure_account의 누적이 버킷을 넘나든다.)")
    return ok


def self_check_stats():
    """
    U·δ·BH·Spearman·AUC·Wilcoxon 구현을 손으로 푼 예제와 맞춘다.
    [09의 self_check_stats + 11의 ρ 셋 + 12의 AUC·Wilcoxon]

    06~11에서 이미 통과한 코드를 왜 또 거는가. 이 파일이 앞 단계를 import
    하는 것이 아니라 복사해 왔기 때문이다. 복사 과정에서 부호 하나가 바뀌어도
    코드는 멀쩡히 돌고 그럴듯한 p값이 나온다. 순위 검정은 틀려도 조용하다.

    ── 예제 1. 완전 분리 ─────────────────────────────────────
        A(그룹1) = [1, 2, 3],  B(그룹2) = [4, 5, 6]
        순위 1 2 3 4 5 6, R_A = 6, n1 = n2 = 3.
        U_A = 6 − 3·4/2 = 0            (A가 이긴 쌍이 하나도 없다)
        δ   = 2·0/9 − 1 = −1.0
        σ²  = (9/12)·[(6+1) − 0] = 5.25
        AUC = U_A/(n1·n2) = 0/9 = 0.0 = (−1+1)/2  ← 두 길이 만난다

    ── 예제 2. 동점 포함 ─────────────────────────────────────
        A(그룹1) = [1, 1, 2],  B(그룹2) = [1, 2, 2]
        1이 자리 1·2·3을 나눠 평균 순위 2, 2가 자리 4·5·6을 나눠 평균 순위 5.
        A의 순위 2, 2, 5 → R_A = 9,  U_A = 9 − 6 = 3.0
        δ   = 2·3/9 − 1 = −1/3 ≈ −0.3333
        σ²  = 동점 묶음 t=3 둘 → Σ(t³−t) = 48
              (9/12)·[7 − 48/30] = 0.75 × 5.4 = 4.05
        AUC = 3/9 = 0.3333 = (−1/3+1)/2  ← 두 길이 만난다

    ── 예제 3. BH 보정 ───────────────────────────────────────
        p = [0.01, 0.02, 0.03, 0.04], m = 4 → p_(i)·m/i 가 넷 다 0.04
        q = [0.04, 0.04, 0.04, 0.04]

    ── 예제 4·5·6. Spearman ──────────────────────────────────
        [11에서 그대로] 완전 양의 단조 → +1.0 · 완전 음의 단조 → −1.0 ·
        동점 포함 x=[1,2,2,3] y=[1,2,3,4] →
            rx = [1, 2.5, 2.5, 4],  ry = [1, 2, 3, 4],  평균은 둘 다 2.5
            Σdx·dy = 4.5,  Σdx² = 4.5,  Σdy² = 5.0
            ρ = 4.5/√22.5 = √0.9 ≈ 0.9486832980505138
        ■ 단축 공식 1−6Σd²/n(n²−1) 로 풀면 0.95가 나와 실패한다. 그것이 이
          예제를 둔 이유다.

    ── 예제 7. AUC 환산 ──────────────────────────────────────
        AUC = (δ+1)/2 이므로
            δ = −1     → 0.000
            δ =  0     → 0.500
            δ = +1     → 1.000
            δ = +0.826 → (0.826+1)/2 = 1.826/2 = 0.913     (06의 we)
        그리고 예제 1·2에서 U 로 낸 AUC와 δ 로 낸 AUC가 같아야 한다.
        한 길만 검사하면 옮겨 적다 생긴 오류를 못 잡는다.

    ── 예제 8·9·10. Wilcoxon 부호순위 ────────────────────────
        손계산은 wilcoxon_signed_rank() 의 docstring에 전부 적어 두었다.
            (8) d = [+1,+2,+3,−4]         → n=4, W+=6, W−=4, r=+0.2
            (9) d = [0,+1,+2,−3,0]        → 0 둘을 버려 n=3, W+=3, W−=3, r=0
           (10) d = [+1,−1,+2,+2]         → |d| 동점 → W+=8.5, W−=1.5, r=+0.7
                                             σ²=7.25(동점 보정), z=1.11413
        (9)가 "0을 버리고 n을 줄인다"의 검사이고, (10)이 "동점 |d|는 평균
        순위, 분산은 Σ(t³−t)/48 만큼 줄인다"의 검사다. 둘 다 빠뜨리기 쉽고
        빠뜨려도 조용히 그럴듯한 p가 나온다.
    """
    print("\n  ── (1) 통계 기계 — U · δ · BH · Spearman · AUC · Wilcoxon ──")
    ok = True

    for name, a, b, exp_u, exp_d, exp_var in SELF_CHECK_U:
        got = mann_whitney(a, b)
        print(f"  {name}  A={a}  B={b}")
        for label, actual, expect in (("U", got["U"], exp_u),
                                      ("δ", got["델타"], exp_d),
                                      ("σ²", got["시그마제곱"], exp_var)):
            good = abs(actual - expect) <= SELF_CHECK_TOL
            ok = ok and good
            print(f"    {label} 기대 {expect:>8.4f} · 실제 {actual:>8.4f} "
                  f"{'통과' if good else '실패'}")
        # 두 길로 낸 AUC가 만나는가
        auc_u = auc_from_u(got["U"], got["n1n2"])
        auc_d = auc_from_delta(got["델타"])
        good = abs(auc_u - auc_d) <= SELF_CHECK_TOL
        ok = ok and good
        print(f"    AUC  U/(n1n2) = {auc_u:.6f} · (δ+1)/2 = {auc_d:.6f}  "
              f"{'통과' if good else '실패'}")

    got_q = bh_qvalues(SELF_CHECK_BH_P)
    good = all(abs(g - e) <= SELF_CHECK_TOL
               for g, e in zip(got_q, SELF_CHECK_BH_Q))
    ok = ok and good
    print(f"  BH 보정  p={SELF_CHECK_BH_P}")
    print(f"    기대 q={SELF_CHECK_BH_Q}")
    print(f"    실제 q={[round(v, 4) for v in got_q]}  "
          f"{'통과' if good else '실패'}")

    print("  Spearman — 순위의 피어슨으로 구현했는가")
    for name, xs, ys, expect in SELF_CHECK_RHO:
        actual = spearman(xs, ys)
        good = actual is not None and abs(actual - expect) <= SELF_CHECK_TOL
        ok = ok and good
        shown = "None" if actual is None else f"{actual:>10.7f}"
        print(f"    {name:<12} 기대 {expect:>10.7f} · 실제 {shown}  "
              f"{'통과' if good else '실패'}")
    print("    (셋째 예제가 동점 사례다. 단축 공식 1−6Σd²/n(n²−1) 로 풀면")
    print("     0.95가 나와 실패한다 — 그것이 이 예제를 둔 이유다.)")

    print("  단독 AUC 환산 — AUC = (δ + 1) / 2")
    for name, delta, expect in SELF_CHECK_AUC:
        actual = auc_from_delta(delta)
        good = abs(actual - expect) <= 1e-9
        ok = ok and good
        print(f"    {lpad(name, 26)} 기대 {expect:>6.3f} · "
              f"실제 {actual:>6.3f}  {'통과' if good else '실패'}")
    print("    (Mann-Whitney의 U1은 '그룹1이 이긴 쌍의 수'이고 ROC-AUC는 그")
    print("     쌍의 비율이다. 두 통계량은 같은 양의 두 이름이라 δ만 있으면")
    print("     분류기 없이 항목별 단독 판별력이 나온다. 새 자유도가 없다.)")

    print("  Wilcoxon 부호순위 — 0 버리기 · |d| 동점 · 연속성 보정")
    for name, diffs, en, ewp, ewm, ez, er in SELF_CHECK_WILCOXON:
        got = wilcoxon_signed_rank(diffs)
        if got is None:
            print(f"    {name:<28} 실패 (0 아닌 쌍이 없다고 판정했다)")
            ok = False
            continue
        checks = (("n", got["n"], en), ("W+", got["Wplus"], ewp),
                  ("W−", got["Wminus"], ewm), ("z", got["z"], ez),
                  ("r", got["r"], er))
        bad = [f"{lab} {act}≠{exp}" for lab, act, exp in checks
               if abs(act - exp) > 1e-9]
        ok = ok and not bad and got["합검산"]
        print(f"    {lpad(name, 28)} n={got['n']} W+={got['Wplus']:.1f} "
              f"W−={got['Wminus']:.1f} z={got['z']:.5f} r={got['r']:+.3f}  "
              f"{'통과' if not bad and got['합검산'] else '실패 ' + ' '.join(bad)}")
    print("    (둘째 예제가 '0인 쌍은 버리고 n을 줄인다'의 검사다. 버리지")
    print("     않으면 아무 차이도 없는 자료에서 유의한 감소가 찍힌다.")
    print("     셋째 예제가 |d| 동점의 평균 순위와 분산 보정 Σ(t³−t)/48 의")
    print("     검사다. W+ + W− = n(n+1)/2 항등식도 함께 확인한다.)")
    return ok


def self_check(nlp, funcword_set):
    """
    두 자가검증을 차례로 걸고, 하나라도 어긋나면 파싱을 시작하지 않는다.

    순서에 뜻이 있다. 통계 기계를 먼저 거는 것은 파이프라인 없이도 되기
    때문이고, 축약형 검사를 뒤에 두는 것은 nlp가 필요하기 때문이다. 둘 다
    통과해야 한 시간짜리 파싱으로 들어간다 — 한 시간을 돌린 뒤에 부정
    표현이 통째로 빠진 표를 발견하는 것보다 여기서 2초 쓰는 편이 훨씬 싸다.
    """
    ok_stats = self_check_stats()
    ok_tok = self_check_contraction(nlp, funcword_set)
    if ok_stats and ok_tok:
        print("\n  두 검사 모두 통과했다. 파싱으로 들어간다.")
        return True

    print()
    print("■ 중단 — 자가검증 실패")
    print("  파싱을 시작하지 않습니다. 이 상태로 돌리면 틀린 표가 조용히 나옵니다.")
    if not ok_stats:
        print("  통계 쪽에서 짚어 볼 곳:")
        print("   · ranks_with_ties 의 평균 순위 — 자리 번호가 1부터인가")
        print("   · U1 = R1 − n1(n1+1)/2 에서 n1이 그룹1의 크기가 맞는가")
        print("   · 분산의 동점 보정 항 Σ(t³−t)/(N(N−1)) 의 부호와 분모")
        print("   · bh_qvalues 의 누적 min 방향 — 큰 p부터 거꾸로 훑는가")
        print("   · spearman 이 단축 공식으로 바뀌지 않았는가 (동점 예제가")
        print("     실패했다면 십중팔구 이것이다)")
        print("   · auc_from_delta 가 (δ+1)/2 인가 — (δ−1)/2 나 δ/2 가 아닌가")
        print("   · wilcoxon_signed_rank 가 0인 쌍을 버리고 n을 줄이는가,")
        print("     |d| 동점에 평균 순위를 주고 분산을 Σ(t³−t)/48 만큼 줄이는가")
        print("   (앞의 다섯은 06→07→08→09→10→11→12로 옮겨 온 코드다. 06과 대조하라.)")
    if not ok_tok:
        print("  토큰화 쪽에서 짚어 볼 곳:")
        print("   · stanza 버전이나 영어 모델이 03·04 실행 때와 달라졌는가")
        print("     (03_설치확인_기록.json·04_기능어측정.json의 '설정'과 대조)")
        print("   · 02_기능어목록.json이 분해형이 아닌 목록으로 바뀌었는가")
        print("   · normalize_apostrophe 가 토큰과 목록 양쪽에 똑같이 걸리는가")
        print("   · measure_account 의 버킷 누적이 버킷 경계를 넘나드는가")
    return False


# ════════════════════════════════════════════════════════════════════════
# [3] 중간 저장 / 이어서 하기 — 04의 방식 그대로
# ════════════════════════════════════════════════════════════════════════
def load_progress():
    """중간 저장 파일이 있으면 읽어 준다. 없으면 None. [04에서 가져옴]"""
    if not os.path.exists(PROGRESS_JSON):
        return None
    return json.load(open(PROGRESS_JSON, encoding="utf-8"))


def save_progress(done, fingerprint, elapsed_total):
    """
    지금까지 끝낸 계정을 통째로 저장한다. [04·11에서 가져옴]

    끝난 계정만 담고 남은 계정 목록은 담지 않는다. 다음 실행이 코퍼스를 다시
    지어 "저장된 것에 없는 계정"을 남은 일로 계산하므로, 목록을 두 벌
    관리하다 어긋나는 일이 없다.

    ■ 12는 코퍼스가 둘이다 ■ 본 코퍼스와 전 텍스트 코퍼스를 한 사전에 담되
    전 텍스트 쪽 uid 에 PRE_KEY 접두사를 붙여 둔다([설정 2]). 같은 계정이
    양쪽에 있으므로 접두사가 없으면 한쪽이 다른 쪽을 조용히 덮어쓴다 —
    그러면 완화 B가 '전 대 전'을 견주게 되고 차이는 전부 0으로 나온다.
    화면에는 아무 이상도 안 찍힌다.

    들여쓰기 없이 쓴다 — 이 파일은 수십 번 다시 쓰이는 작업용이다.
    """
    write_json(PROGRESS_JSON, {
        "안내": "12번의 중간 저장 파일입니다. 측정이 끝나면 자동으로 지워집니다.",
        "지문": fingerprint,
        "완료계정수": len(done),
        "누적소요초": round(elapsed_total, 1),
        "저장시각": time.strftime("%Y-%m-%d %H:%M:%S"),
        "계정": done,
    })


def run_measurement(nlp, work, funcword_set, fp):
    """
    계정을 하나씩 파싱해 카운트한다. 여기가 40분~80분이다.

    work — {내부uid: [(문서, 버킷이름), ...]}. 본 코퍼스는 FOX8_KEY,
    전 텍스트 코퍼스는 PRE_KEY 접두사가 붙은 채로 들어온다. 둘을 한 벌로
    돌리는 이유는 docstring 「실행」 절에 적었다 — 두 번 나누어 돌리면 두
    파싱 사이에 stanza 버전이 달라질 여지가 생긴다.

    04의 [5/5]와 같은 구조다 — uid 오름차순 고정, 처음 WARMUP_ACCOUNTS
    계정의 실측 속도로 이 실행의 끝을 추정, CHECKPOINT_EVERY 계정마다 중간
    저장. 계정당 문서 수가 10~200건으로 제각각이라 '계정당 평균'으로 환산하면
    큰 계정이 몰린 구간에서 크게 빗나가므로 문서당 속도로 환산한다.

    반환: (계정별 측정치, 이번 실행 소요초, 누적 소요초). 이어받기 실패 시 None.
    """
    done, prev_sec = {}, 0.0
    prog = load_progress()
    if prog:
        if prog.get("지문") != fp:
            print("■ 중단 — 중간 저장 파일과 지금의 입력이 다릅니다.")
            print(f"  저장 당시: {prog.get('지문')}")
            print(f"  지금:      {fp}")
            print("  02가 다시 돌았거나 코퍼스 구축 코드가 바뀐 것으로 보입니다.")
            print("  기준이 다른 수치를 이어 붙이면 한 파일 안에 서로 다른 잣대가")
            print("  섞이고, 나중에 눈으로는 찾을 수 없습니다.")
            print(f"  → {PROGRESS_JSON} 을(를) 지우고 처음부터 다시 실행하십시오.")
            return None
        done = prog["계정"]
        prev_sec = prog.get("누적소요초", 0.0)
        print(f"      중간 저장을 찾았습니다 — 완료 {len(done):,}계정 "
              f"(그때까지 {fmt_dur(prev_sec)})")
        print("      끝난 계정은 건너뛰고 이어서 합니다.")
    else:
        print("      중간 저장 없음. 처음부터 시작합니다.")

    # 계정 순서를 uid 오름차순으로 고정한다. 실행할 때마다 순서가 달라지면
    # "몇 번째까지 했다"는 말이 뜻을 잃는다.
    todo = [uid for uid in sorted(work) if uid not in done]
    todo_docs = sum(len(work[uid]) for uid in todo)
    n_total = fp["본_계정수"] + fp["전_계정수"]
    print(f"      남은 계정 {len(todo):,}개 · 문서 {todo_docs:,}건")
    if todo_docs:
        print(f"      04 실측 {REF_MS_PER_DOC:.0f} ms/문서면 "
              f"{fmt_dur(todo_docs * REF_MS_PER_DOC / 1000)}, "
              f"트윗이 짧아 {FAST_MS_PER_DOC:.0f} ms/문서면 "
              f"{fmt_dur(todo_docs * FAST_MS_PER_DOC / 1000)}입니다.")
        print(f"      (04는 문서 {REF_04_DOCS:,}건에 {REF_04_MINUTES}분이 걸렸다. "
              "트윗은 글자 수 상한이 있어 레딧 글보다 짧다 —")
        print("       아래 20계정 워밍업 실측으로 다시 잡는다.)")
    if not todo:
        print("      남은 계정이 없습니다. 저장된 측정치로 바로 넘어갑니다.")
        return done, 0.0, prev_sec

    print(f"      {CHECKPOINT_EVERY}계정마다 중간 저장합니다. 창을 닫아도 됩니다.")
    t_run = time.time()
    docs_run = 0

    for i, uid in enumerate(todo, 1):
        items = work[uid]
        done[uid] = measure_account(nlp, [t for t, _ in items],
                                    [k for _, k in items], funcword_set)
        docs_run += len(items)

        if i == WARMUP_ACCOUNTS:
            el = time.time() - t_run
            per_doc = el / docs_run
            left = (todo_docs - docs_run) * per_doc
            print()
            print(f"      ── 속도 실측 (처음 {WARMUP_ACCOUNTS}계정) ──")
            print(f"         문서 {docs_run:,}건 · {el:.1f}초 "
                  f"→ {per_doc * 1000:.0f} ms/문서")
            print(f"         남은 문서 {todo_docs - docs_run:,}건 "
                  f"→ 예상 {fmt_dur(left)}")
            print(f"         (04는 {REF_MS_PER_DOC:.0f} ms/문서였다. 크게 다르면 "
                  "다른 기계이거나 다른 구성이거나,")
            print("          트윗과 레딧 글의 길이 차이가 드러난 것이다.)")
            print()

        if i % CHECKPOINT_EVERY == 0:
            el = time.time() - t_run
            save_progress(done, fp, prev_sec + el)
            per_doc = el / docs_run
            left = (todo_docs - docs_run) * per_doc
            print(f"      {len(done):,}/{n_total:,} 계정 · "
                  f"경과 {fmt_dur(el)} · 잔여 추정 {fmt_dur(left)} · 저장 완료")

    run_sec = time.time() - t_run
    print(f"      {len(done):,}/{n_total:,} 계정 완료 · "
          f"이번 실행 {fmt_dur(run_sec)}")
    return done, run_sec, prev_sec + run_sec


# ════════════════════════════════════════════════════════════════════════
# [4-가] 사용률 — 05의 분모 규칙 (사전선언 05-06 결정 1)
# ════════════════════════════════════════════════════════════════════════
def compute_rates(measures, prefix=""):
    """
    계정마다 단어별 사용률과 총 사용률을 낸다. [05·11에서 가져옴]

    분모는 토큰수_구두점제외 하나로 고정이다(05-06 사전선언 결정 1). 구두점
    습관은 R 블록이 다룰 신호라 F 블록과 섞지 않는다. 트윗은 구두점 습관이
    레딧과 크게 다를 수 있어(해시태그·말줄임·이모지) 이 분리가 12에서 더
    중요하다.

    희소 저장은 04·05의 방식을 그대로 잇는다 — 0회인 단어는 담지 않는다.
    없는 키 = 0으로 읽으면 되고, 아래 word_vector()가 그 규약을 지킨다.

    prefix — 계정에 붙일 접두사([설정 2]). 트위터 user_id와 레딧 계정 ID가
    우연히 같아도 두 자료가 한 사전에서 서로를 덮어쓰지 않게 한다.

    자릿수도 05와 같은 RATE_DIGITS로 자른다. 05가 저장해 둔 BotSim 사용률과
    같은 눈금이어야 두 무더기를 견줄 수 있다.
    """
    rates, undefined = {}, []
    for uid in sorted(measures):
        a = measures[uid]
        denom = a["토큰수_구두점제외"]
        if denom == 0:
            undefined.append(uid)
            continue
        counts = a["기능어"]
        rates[prefix + uid] = {
            "총사용률": round(sum(counts.values()) / denom, RATE_DIGITS),
            "분모": denom,
            "사용률": {w: round(n / denom, RATE_DIGITS)
                     for w, n in counts.items()},
        }
    return rates, undefined


def word_vector(uids, rates, word):
    """
    한 단어에 대해, 주어진 계정들의 사용률을 순서대로 늘어놓는다. [06·09·10·11에서]

    ■ 여기가 F 블록에서 가장 틀리기 쉬운 한 줄이다. ■
    사용률은 '희소 저장'이라 한 번도 안 쓴 단어는 그 계정의 사전에 아예 키가
    없다. 그래서 .get(word, 0.0) 의 기본값 0.0이 반드시 있어야 한다. 없는
    키를 건너뛰면 "그 단어를 한 번도 안 쓴 계정"이 통째로 표본에서 사라지고,
    정작 재려던 '덜 쓴다'가 바로 그 사라진 0들이다. 결과 전체가 뒤집힌다.
    """
    return [rates[u]["사용률"].get(word, 0.0) for u in uids]


def word_presence(uids, rates, words):
    """주어진 표본 안에서 각 단어를 한 번이라도 쓴 계정 수. [09에서 가져옴]"""
    out = {w: 0 for w in words}
    for u in uids:
        used = rates[u]["사용률"]
        for w in words:
            if used.get(w, 0.0) > 0:
                out[w] += 1
    return out


# ════════════════════════════════════════════════════════════════════════
# [4-나] 분모 규칙 — 07의 축 판별 블록을 통째로 가져온다
# ────────────────────────────────────────────────────────────────────────
# build_axis_map · axis_of · denom_kind_of · compute_ratios ·
# compute_upos_ratios · defined_values 는 07_형태자질비교.py 에서 한 글자도
# 고치지 않고 가져왔다(08·09·10·11도 같은 코드를 쓴다).
#
# ■ 축은 어디에서 유도하나 — 12의 결정 ■
# 명세가 "축 판별은 BotSim(04) + fox8을 합친 자료에서 유도"하라고 적었고,
# 11이 IRA에 쓴 것과 같은 이유다. 축 내부 비율의 분모는 "그 축이 몇 번
# 나왔나"인데, 두 자료에서 따로 유도하면 같은 이름의 축이 서로 다른 값
# 목록을 가질 수 있고(예: 한쪽에만 Gender=Neut 이 있으면) 그러면 분모의
# 정의가 갈린다. 눈금이 다른 두 δ를 한 산점도에 놓는 것은 아무 뜻이 없다.
#
# 합쳐서 유도하면 07의 축 목록과 달라질 수 있다 — fox8에만 있는 값이 축의
# 값 종수를 늘리기 때문이다. 그래서 [5/9]가 07의 축분류와 대조해 다르면
# 경고와 표를 찍는다. 규칙은 따라가되, 눈금이 바뀐 사실은 반드시 드러나야
# 한다.
#
# ■ 축은 한 번만 유도한다 ■ 완화 A·B와 보조 분석도 같은 축 지도를 쓴다.
# 부분집합마다 축을 다시 유도하면 부분집합마다 분모의 정의가 달라져,
# "시기를 좁혔더니 δ가 줄었다"가 사실은 "분모가 바뀌었다"일 수 있게 된다.
# ════════════════════════════════════════════════════════════════════════
def build_axis_map(measures):
    """
    자료 전체를 훑어 축마다 어떤 값들이 나타나는지 모은다. [07에서 가져옴]

    12는 여기에 **04의 계정 전부 + fox8 계정 전부**를 넘긴다(위 주석 참조).

    반환: {축 이름: 정렬된 값 목록}
    """
    axis_values = {}
    for a in measures.values():
        for key in a.get("자질", {}):
            axis, sep, val = key.partition("=")
            if not sep:
                axis, val = key, ""
            axis_values.setdefault(axis, set()).add(val)
    return {ax: sorted(vs) for ax, vs in axis_values.items()}


def axis_of(key):
    """자질 키에서 축 이름만 떼어 낸다. [07에서 가져옴] "="가 없으면 키 전체가 축이다."""
    return key.split("=", 1)[0]


def denom_kind_of(key, axis_map):
    """
    이 자질에 어떤 분모를 쓸지 정한다. [07에서 가져옴] 사전선언 07의 표 그대로다.

        대립값 ≥ 2  →  그 계정의 해당 축 총 출현수      (DENOM_AXIS)
        대립값 = 1  →  그 계정의 토큰수_구두점제외      (DENOM_TOKEN)
    """
    return DENOM_AXIS if len(axis_map.get(axis_of(key), [""])) >= 2 else DENOM_TOKEN


def compute_ratios(measures, keys, axis_map):
    """
    계정마다 자질 비율을 낸다. [07에서 가져옴] 반환은 (판정용, 보조용, 출현계정수).

    없는 키는 0회다 — 결측이 아니다. 결측 판정은 오로지 분모로만 한다.
        Tense=Past 0회, Tense=Pres 12회  →  0 / 12 = 0.0    (값이 있다)
        Tense 축 자체가 0회              →  0 / 0  = 결측   (나눗셈 불성립)
    """
    kinds = {k: denom_kind_of(k, axis_map) for k in keys}
    ratios, aux, presence = {}, {}, {k: 0 for k in keys}

    for uid in sorted(measures):
        a = measures[uid]
        feats = a.get("자질", {})
        denom_tok = a.get("토큰수_구두점제외", 0)

        axis_total = {}
        for k, n in feats.items():
            ax = axis_of(k)
            axis_total[ax] = axis_total.get(ax, 0) + n

        row, arow = {}, {}
        for k in keys:
            cnt = feats.get(k, 0)          # ← 없는 키는 0회. 위 설명을 보라.
            if cnt:
                presence[k] += 1
            if kinds[k] == DENOM_AXIS:
                d = axis_total.get(axis_of(k), 0)
            else:
                d = denom_tok
            row[k] = None if d == 0 else cnt / d
            arow[k] = None if denom_tok == 0 else cnt / denom_tok
        ratios[uid] = row
        aux[uid] = arow
    return ratios, aux, presence


def compute_upos_ratios(measures, keys):
    """
    품사 비율. [07에서 가져옴] 분모는 언제나 토큰수_구두점제외다(사전선언 07).

    PUNCT 줄만은 분모가 구두점을 뺀 수인데 분자는 구두점 수라 '말 토큰 대비
    구두점'이라는 다른 뜻의 값이 된다. 07·08·09·10·11이 그랬듯 12도 그 줄을
    해석하지 않는다.
    """
    ratios, presence = {}, {k: 0 for k in keys}
    for uid in sorted(measures):
        a = measures[uid]
        pos = a.get("UPOS", {})
        denom = a.get("토큰수_구두점제외", 0)
        row = {}
        for k in keys:
            cnt = pos.get(k, 0)            # ← 없는 키는 0회 (자질과 같은 규율)
            if cnt:
                presence[k] += 1
            row[k] = None if denom == 0 else cnt / denom
        ratios[uid] = row
    return ratios, presence


def defined_values(uids, ratios, key):
    """
    결측(None)을 뺀 값만 순서대로 늘어놓는다. [07에서 가져옴]

    결측은 그 자질의 검정에서만 빠진다. 계정이 통째로 빠지는 것이 아니라
    칸 하나가 빠지는 것이라, 같은 계정이 Tense 검정에는 들어가고 Mood 검정에는
    빠질 수 있다. 그래서 유효 계정 수가 자질마다 다르고, 표에 그 수를 싣는다.
    """
    out = []
    for u in uids:
        v = ratios[u][key]
        if v is not None:
            out.append(v)
    return out


def compare_axis_map(axis_map, base_axes):
    """
    12가 유도한 축과 07의 축분류를 대조한다. 눈금이 바뀌었는지를 보는 자리다.
    [11에서 가져옴 · 이름만 fox8로]

    07 JSON의 "축분류"는 {축: {값종수, 값목록, 분모종류, 자질수}} 꼴이다.
    세 가지를 본다.
        · 07에 있던 축이 12에서 사라졌는가
        · 12에 새로 생긴 축이 있는가 (fox8에만 있는 자질)
        · 남은 축에서 값 목록이 달라졌는가 — 특히 **분모 종류가 바뀐 축**

    분모 종류가 바뀐 축이 가장 위험하다. 07에서는 토큰수 대비 비율이던
    자질이 12에서는 축 내부 비율이 되면, 같은 이름의 두 δ가 서로 다른 것을
    재고 있는데 산점도에서는 한 점으로 찍힌다. 따로 세어 크게 찍는다.

    반환: (기록용 사전, 분모 종류가 바뀐 축 목록)
    """
    now = {ax: sorted(vals) for ax, vals in axis_map.items()}
    before = {ax: list(info.get("값목록") or [])
              for ax, info in (base_axes or {}).items()}

    gone = sorted(set(before) - set(now))
    added = sorted(set(now) - set(before))
    changed, denom_changed = [], []
    for ax in sorted(set(now) & set(before)):
        if now[ax] != before[ax]:
            changed.append({"축": ax, "07값": before[ax], "12값": now[ax]})
        kind_before = DENOM_AXIS if len(before[ax]) >= 2 else DENOM_TOKEN
        kind_now = DENOM_AXIS if len(now[ax]) >= 2 else DENOM_TOKEN
        if kind_before != kind_now:
            denom_changed.append({"축": ax, "07분모": kind_before,
                                  "12분모": kind_now})
    return {
        "07축수": len(before), "12축수": len(now),
        "사라진축": gone, "새로생긴축": added,
        "값목록이_달라진축": changed,
        "분모종류가_바뀐축": denom_changed,
        "동일": not (gone or added or changed),
    }, denom_changed


# ════════════════════════════════════════════════════════════════════════
# [4-다] 비교 — 07의 compare_family를 getter로 일반화한 것 [11에서 가져옴]
# ════════════════════════════════════════════════════════════════════════
def compare_family(keys, g1_ids, g2_ids, getter, presence, sparse_cut,
                   kinds=None, subj="봇이"):
    """
    한 가족을 통째로 검정하고 BH를 건다. [07의 compare_family + 09의 getter 방식]

    계산은 07과 한 글자도 다르지 않다. 달라진 것은 값을 꺼내는 방법을 밖에서
    넣어 준다는 것뿐이다 — F 블록은 사용률에서(word_vector), M·UPOS는 07의
    분모 규칙으로 만든 비율에서(defined_values) 꺼낸다.

    그룹1 = 봇, 그룹2 = 사람이다([설정 4]). δ > 0 이면 봇이 높다. 06·07과
    같은 부호 규약이다.

    ■ 단독 AUC를 여기서 함께 낸다 ■ 결정 0-2가 요구한 특징별 단독 효과다.
    AUC = (δ+1)/2 이므로 새로 계산할 것이 없고, U 로 낸 값과 어긋나지
    않는지를 그 자리에서 검산해 '환산검산' 칸에 남긴다.

    ■ BH 가족에서 검정 불가 항목을 빼는 이유 ■
    한쪽 무더기가 비면 U를 계산할 수 없다. p가 없는 항목을 BH에 넣을 방법이
    없으므로(m만 부풀린다) 가족에서 뺀다. 뺀 개수는 화면과 JSON에 그대로
    적는다 — m이 58이 아니라 56이었다는 사실은 q값의 뜻을 바꾸므로 숨기면
    안 된다. 이것은 사후 문턱이 아니다. 문턱은 "값이 있는데 작아서 버리는
    것"이고, 여기는 값 자체가 없다.

    반환: (|δ| 내림차순 (키, 결과) 목록, 검정 가능 항목 수)
    """
    n_all = len(g1_ids) + len(g2_ids)
    rows = []
    for k in keys:
        v1 = getter(g1_ids, k)
        v2 = getter(g2_ids, k)
        r = {
            "축": axis_of(k),
            "분모종류": (kinds or {}).get(k, DENOM_TOKEN),
            "봇_유효n": len(v1),
            "사람_유효n": len(v2),
            "결측계정수": n_all - len(v1) - len(v2),
            "출현계정수": presence.get(k, 0),
            "희소": presence.get(k, 0) < sparse_cut,
        }
        if not v1 or not v2:
            r.update({"검정가능": False, "U": None, "z": None, "p": None,
                      "q": None, "델타": None, "방향": "검정 불가",
                      "봇_중앙": None, "사람_중앙": None,
                      "단독AUC": None, "AUC세기": None, "환산검산": None,
                      "유의": False, "주목": False})
        else:
            res = mann_whitney(v1, v2)
            auc_d = auc_from_delta(res["델타"])
            auc_u = auc_from_u(res["U"], res["n1n2"])
            r.update({"검정가능": True, "U": res["U"], "z": res["z"],
                      "p": res["p"], "델타": res["델타"],
                      "방향": direction_of(res["델타"], subj),
                      "봇_중앙": statistics.median(v1),
                      "사람_중앙": statistics.median(v2),
                      "단독AUC": auc_d,
                      "AUC세기": auc_strength(auc_d),
                      "환산검산": abs(auc_d - auc_u) <= 1e-9})
        rows.append((k, r))

    testable = [(k, r) for k, r in rows if r["검정가능"]]
    qs = bh_qvalues([r["p"] for _, r in testable])
    for (k, r), q in zip(testable, qs):
        r["q"] = q
        r["유의"] = q <= Q_ALPHA
        r["주목"] = r["유의"] and abs(r["델타"]) >= DELTA_NOTABLE

    # 검정 불가는 |δ|를 −1로 쳐서 맨 뒤로 보낸다(δ의 하한이 −1이라 겹치지 않는다).
    rows.sort(key=lambda kv: -(abs(kv[1]["델타"]) if kv[1]["검정가능"] else -1.0))
    return rows, len(testable)


def family_summary(rows, n_family, sparse_cut, n_all, label):
    """가족 하나의 요약을 찍는다. [07·11의 family_summary · 주어만 봇으로]"""
    sig_n = sum(1 for _, r in rows if r["유의"])
    notable = [(k, r) for k, r in rows if r["주목"]]
    up = sum(1 for _, r in notable if r["델타"] > 0)
    down = sum(1 for _, r in notable if r["델타"] < 0)
    sparse_n = sum(1 for _, r in notable if r["희소"])
    untestable = sum(1 for _, r in rows if not r["검정가능"])
    bad_conv = sum(1 for _, r in rows if r["환산검산"] is False)

    print(f"\n      [{label}] BH 가족 크기                  {n_family:>4}종 "
          f"/ {len(rows)}종")
    if untestable:
        print(f"        검정 불가로 가족에서 빠짐           {untestable:>4}종")
    print(f"        유의 (q ≤ {Q_ALPHA})                      {sig_n:>4}종")
    print(f"        주목 (q ≤ {Q_ALPHA} 그리고 |δ| ≥ {DELTA_NOTABLE})   "
          f"{len(notable):>4}종")
    print(f"          봇이 높음                          {up:>4}종")
    print(f"          봇이 낮음                          {down:>4}종")
    print(f"          그중 희소 표시                     {sparse_n:>4}종")
    print(f"        (희소 = 그 항목이 나온 계정이 {sparse_cut:,}개 미만 — "
          f"비교 표본 {n_all:,}계정의 {SPARSE_FRAC:.0%})")
    if bad_conv:
        print(f"        ■ AUC 환산 검산 실패 {bad_conv}종 — (δ+1)/2 와 U/(n1n2)가")
        print("          어긋났다. 순위 계산이 두 곳에서 갈렸다는 뜻이다.")
    return {
        "가족크기": n_family,
        "대상종수": len(rows),
        "검정불가": untestable,
        "유의": sig_n,
        "주목": len(notable),
        "봇이높음": up,
        "봇이낮음": down,
        "희소포함": sparse_n,
        "AUC환산검산_실패": bad_conv,
        "주목목록": [k for k, _ in notable],
    }


# ════════════════════════════════════════════════════════════════════════
# [5] 방향 벡터 짝짓기와 상관 — 전이 판정의 뼈대  [11에서 가져옴]
# ════════════════════════════════════════════════════════════════════════
def pair_with_baseline(rows, baseline):
    """
    12의 δ에 06·07의 δ를 나란히 붙이고 부호 일치를 판정한다.

    ■ 각 칸의 뜻 ■
        BotSim델타   06 또는 07이 낸 δ (BotSim 봇 대 BotSim 사람)
        fox8델타     12가 낸 δ (fox8 봇 대 fox8 사람)
        BotSim주목   앞 단계에서 q ≤ 0.05 이면서 |δ| ≥ 0.147 이었는가
        주목         12에서 같은 두 조건을 넘었는가
        부호일치     두 δ의 부호가 같은가
        단독AUC      (δ_fox8 + 1)/2 — 그 항목 하나로 낸 판별력
        추적         BotSim에서 주목이었던 항목이 fox8에서 어떻게 되었나

    ■ δ가 정확히 0인 항목을 어떻게 다루나 ■
    부호일치를 None으로 둔다. 0은 "같은 방향"도 "다른 방향"도 아니다.
    한쪽으로 몰아 넣으면 "아무도 그 단어를 안 썼다"는 사실이 방향 주장으로
    둔갑한다. 일치율의 분모에서도 뺀다(그 수를 따로 보고한다).

    ■ '유지/약화/역방향' — 12가 쓰는 어휘 ■
    08·10은 같은 자료를 다른 조건으로 다시 잰 것이라 '유지/무너짐'을 물을
    수 있었고, 11은 다른 자료라 방향만 물었다. 12는 그 중간이다 — 다른
    자료지만 **같은 물음**(봇 대 사람)을 던지므로 "옮겨 갔는가"를 물을 수
    있다. 다만 '무너짐'이라는 말은 쓰지 않는다. fox8에서 작다고 BotSim의
    값이 틀린 것이 아니기 때문이다. 그래서 약화라고 적는다.
        역방향   부호가 반대
        유지     부호가 같고 |δ_fox8| ≥ 0.147
        약화     부호가 같고 |δ_fox8| < 0.147
    """
    out = []
    for k, r in rows:
        b = (baseline or {}).get(k) or {}
        d_old = b.get("델타")
        prior_notable = bool(b.get("주목"))
        d_new = r["델타"] if r["검정가능"] else None

        if d_old is None or d_new is None or d_old == 0.0 or d_new == 0.0:
            same = None
        else:
            same = (d_old > 0) == (d_new > 0)

        if d_new is None:
            track = "검정불가"
        elif same is None:
            track = "방향 없음"
        elif not same:
            track = "역방향"
        elif abs(d_new) >= DELTA_NOTABLE:
            track = "유지"
        else:
            track = "약화"

        out.append((k, {
            "BotSim델타": d_old,
            "BotSim주목": prior_notable,
            "BotSimAUC": rnd(auc_from_delta(d_old), STAT_DIGITS),
            "fox8델타": rnd(d_new, STAT_DIGITS),
            "차이": rnd(d_new - d_old, STAT_DIGITS)
                  if (d_old is not None and d_new is not None) else None,
            "q": sig(r.get("q")),
            "방향": r.get("방향"),
            "주목": bool(r.get("주목")),
            "부호일치": same,
            "추적": track,
            "단독AUC": rnd(r.get("단독AUC"), STAT_DIGITS),
            "AUC세기": rnd(r.get("AUC세기"), STAT_DIGITS),
            "봇_유효n": r.get("봇_유효n"),
            "사람_유효n": r.get("사람_유효n"),
            "출현계정수": r.get("출현계정수"),
            "희소": bool(r.get("희소")),
        }))
    return out


def correlation_block(pairs, only_prior_notable=False):
    """
    한 가족의 δ 벡터 상관과 방향 일치율을 낸다. [11에서 가져옴]

    only_prior_notable=True 면 06·07에서 주목이었던 항목만 추린다.

    ■ 왜 따로 내나 ■
    가족 전체에는 δ가 0 근처인 항목이 많다. 그런 항목의 δ는 대부분 잡음이라
    두 자료에서 서로 무관하게 흩어지고, 그 흩어짐이 상관을 0 쪽으로 끌어
    내린다(희석). 그래서 전체 ρ가 낮아도 "주목 항목에서는 잘 맞는다"가
    성립할 수 있다. 두 값을 나란히 놓아야 이 구분이 보인다.

    ■ 그런데 판정에는 전체를 쓴다 ■
    "주목이었던 것만 고른다"는 선택은 앞 단계 결과를 보고 하는 선택이다.
    예측 1의 판정에 그것을 쓰면 사전등록의 뜻이 옅어진다.

    반환: 기록용 사전. x·y 벡터도 함께 담아 산점도가 다시 계산하지 않게 한다.
    """
    xs, ys, keys = [], [], []
    for k, c in pairs:
        if c["BotSim델타"] is None or c["fox8델타"] is None:
            continue
        if only_prior_notable and not c["BotSim주목"]:
            continue
        keys.append(k)
        xs.append(c["BotSim델타"])
        ys.append(c["fox8델타"])

    rho = spearman(xs, ys)
    zero = sum(1 for x, y in zip(xs, ys) if x == 0.0 or y == 0.0)
    judged = len(xs) - zero
    same = sum(1 for x, y in zip(xs, ys)
               if x != 0.0 and y != 0.0 and (x > 0) == (y > 0))
    return {
        "항목수": len(xs),
        "rho": rnd(rho, STAT_DIGITS),
        "방향일치수": same,
        "방향판정대상": judged,
        "방향일치율": rnd(same / judged, 4) if judged else None,
        "델타0_제외수": zero,
        "x_BotSim": xs,
        "y_fox8": ys,
        "항목목록": keys,
    }


def print_correlation(label, whole, notable):
    """가족 하나의 상관 두 벌(전체·주목 한정)을 나란히 찍는다. [11에서 가져옴]"""
    def fmt(block):
        rho = block["rho"]
        rate = block["방향일치율"]
        return (f"{block['항목수']:>5}종   "
                f"ρ = {('  —' if rho is None else f'{rho:+.4f}')}   "
                f"방향 일치 {block['방향일치수']:>4}/{block['방향판정대상']:<4}"
                f"({'  —' if rate is None else f'{rate:.1%}'})")

    print(f"\n      [{label}]")
    print(f"        가족 전체      {fmt(whole)}")
    print(f"        앞 주목 한정   {fmt(notable)}")
    if whole["델타0_제외수"]:
        print(f"        (δ가 정확히 0이라 방향 판정에서 뺀 항목 "
              f"{whole['델타0_제외수']}종. ρ 계산에는 들어간다.)")


def print_pair_table(pairs, base_label, title, limit=None):
    """
    δ_BotSim 과 δ_fox8 을 한 줄에 놓고 단독 AUC와 추적 판정을 붙인다.
    [08·10·11의 대조표를 12의 판정에 맞게]
    """
    shown = pairs if limit is None else pairs[:limit]
    if not shown:
        print("\n      띄울 줄이 없습니다.")
        return
    print(f"\n      {title}")
    print(f"      항목          {base_label} δ   fox8 δ      차이   단독AUC"
          "          q  추적    비고")
    for k, c in shown:
        if c["fox8델타"] is None or c["BotSim델타"] is None:
            reason = ("12 검정불가" if c["fox8델타"] is None
                      else f"{base_label}에 없음")
            print(f"      {k:<12}{'—':>7}{'—':>9}{'—':>10}{'—':>9}{'—':>11}  "
                  f"{'—':<6}  {reason}")
            continue
        note = []
        if c["BotSim주목"]:
            note.append(f"{base_label}주목")
        if c["주목"]:
            note.append("12주목")
        if c["희소"]:
            note.append("희소")
        print(f"      {k:<12}{c['BotSim델타']:>+7.3f}{c['fox8델타']:>+9.3f}"
              f"{c['차이']:>+10.3f}{c['단독AUC']:>9.3f}{c['q']:>11.4f}  "
              f"{lpad(c['추적'], 6)}  {' '.join(note)}")


# ════════════════════════════════════════════════════════════════════════
# [6] 단독 AUC 표와 누적 기여 — 결정 0-2 · 치명 1의 재발 방지
# ────────────────────────────────────────────────────────────────────────
# 봉인 라인이 남긴 교훈은 하나로 줄일 수 있다. **결합 점수만 보고하면
# 그 점수의 실체를 아무도 못 본다.** 0.8549라는 수는 열 항목이 힘을 모은
# 것처럼 보였지만 실제로는 한 항목이었다.
#
# 그래서 12는 결합 점수를 아예 만들지 않고(사전선언 결정 3) 항목별 단독
# AUC 표를 낸다. 표를 |AUC − 0.5| 내림차순으로 세우면 "누가 얼마를
# 설명하는가"가 첫 줄부터 보인다.
#
# 누적 기여는 그 편중을 한 수로 줄인 것이다.
#       1위 점유율   = 1위의 |AUC−0.5|  ÷  상위 10종의 |AUC−0.5| 합
# 열 항목이 고르게 나뉘면 10%, 한 항목이 다 하면 100%에 가깝다.
#
# ■ 이 수는 치명 1의 94%와 같은 양이 아니다 ■ 치명 1의 94%는 상위 10개를
# **결합한** 점수(AUC 0.8549)에서 한 항목이 차지하는 몫이고, 여기 것은 단독
# AUC들의 크기 비다. 결합 점수를 만들지 않기로 했으므로 같은 양을 낼 수
# 없다. 같은 자리를 다른 자로 재는 것이며, 화면에도 그렇게 적는다.
# ════════════════════════════════════════════════════════════════════════
def auc_ranking(pairs_by_family, families):
    """
    세 가족의 항목을 한 줄로 모아 |AUC − 0.5| 내림차순으로 세운다.

    가족을 섞어 세우는 이유 — 결정 0-2가 묻는 것은 "어느 가족이 센가"가
    아니라 "**어느 항목 하나가** 얼마를 설명하는가"다. 가족별로 따로 세우면
    각 가족의 1위가 세 개 나와 편중이 셋으로 나뉘어 보인다.

    반환: [(가족, 항목, AUC, |AUC−0.5|, δ, q, BotSim주목), ...] 내림차순
    """
    rows = []
    for family in families:
        for k, c in pairs_by_family[family]:
            if c["단독AUC"] is None:
                continue
            rows.append({
                "가족": family, "항목": k,
                "AUC": c["단독AUC"], "세기": c["AUC세기"],
                "델타": c["fox8델타"], "q": c["q"],
                "BotSim델타": c["BotSim델타"],
                "BotSim주목": c["BotSim주목"],
                "주목": c["주목"], "희소": c["희소"],
            })
    rows.sort(key=lambda r: -(r["세기"] or 0.0))
    return rows


def concentration(rows, top_n=AUC_CUM):
    """
    누적 기여 — 상위 top_n 종에서 1위와 상위 3종이 차지하는 몫.

    고르게 나뉘면 1위는 1/top_n 이다. 그 값도 함께 담아 표에서 곧바로
    견줄 수 있게 한다.
    """
    top = rows[:top_n]
    total = sum(r["세기"] for r in top)
    if not top or total <= 0:
        return None
    return {
        "상위n": len(top),
        "세기합": round(total, 6),
        "1위항목": f"{top[0]['가족']}·{top[0]['항목']}",
        "1위세기": round(top[0]["세기"], 6),
        "1위점유율": round(top[0]["세기"] / total, 4),
        "상위3점유율": round(sum(r["세기"] for r in top[:3]) / total, 4),
        "균등배분시_1위점유율": round(1.0 / len(top), 4),
        "목록": [{"가족": r["가족"], "항목": r["항목"], "AUC": r["AUC"],
                "세기": round(r["세기"], 6),
                "점유율": round(r["세기"] / total, 4)} for r in top],
    }


def print_auc_table(rows, conc, title, limit=AUC_TOP):
    """단독 AUC 표를 |AUC−0.5| 내림차순으로 찍는다."""
    print(f"\n      {title}")
    if not rows:
        print("      띄울 줄이 없습니다.")
        return
    print("      순위  가족        항목            fox8 δ   단독AUC  |AUC−.5|"
          "   BotSim δ  비고")
    for i, r in enumerate(rows[:limit], 1):
        note = []
        if r["BotSim주목"]:
            note.append("앞주목")
        if r["희소"]:
            note.append("희소")
        base = ("     —" if r["BotSim델타"] is None
                else f"{r['BotSim델타']:>+7.3f}")
        print(f"      {i:>4}  {lpad(r['가족'], 10)}{r['항목']:<16}"
              f"{r['델타']:>+8.3f}{r['AUC']:>9.3f}{r['세기']:>10.3f}"
              f"{base:>11}  {' '.join(note)}")
    if conc is None:
        print("\n      누적 기여를 낼 수 없다(세기 합이 0이다).")
        return
    print(f"\n      ── 누적 기여 (상위 {conc['상위n']}종의 |AUC−0.5| 합 기준) ──")
    print(f"        1위        {conc['1위항목']}  |AUC−0.5| = "
          f"{conc['1위세기']:.4f}")
    print(f"        1위 점유율  {conc['1위점유율']:.1%}   "
          f"(고르게 나뉘면 {conc['균등배분시_1위점유율']:.1%})")
    print(f"        상위 3 점유율 {conc['상위3점유율']:.1%}")
    print()
    print("        ■ 이 수를 봉인 라인의 94%와 같은 것으로 읽지 말 것 ■")
    print(f"        치명 1의 {SEALED_WAS_SHARE:.0%}는 상위 10개를 **결합한** 점수")
    print(f"        (AUC {SEALED_TOP10_AUC})에서 `{PRED2_WORD}` 하나가 차지한 몫이고,")
    print("        위의 점유율은 **단독** AUC들의 크기 비다. 결합 점수를 만들지")
    print("        않기로 했으므로(사전선언 결정 3) 같은 양을 낼 수 없다.")
    print("        같은 자리를 다른 자로 재는 것이다.")


def head_tracking(pairs_by_family, families):
    """
    BotSim에서 주목이었던 항목이 fox8에서 어떻게 되었는지 세고, 명세가 지목한
    머리 항목(we·must·our·was·he · Tense=Past·Number=Sing·Gender 계열)을
    따로 뽑는다.

    반환: (가족별 집계, 머리 항목 표)
    """
    summary, head_rows = {}, []
    for family in families:
        cnt = Counter()
        for k, c in pairs_by_family[family]:
            if not c["BotSim주목"]:
                continue
            cnt[c["추적"]] += 1
        summary[family] = {"앞주목수": sum(cnt.values()), **dict(cnt)}

    picked = set()
    for family in families:
        for k, c in pairs_by_family[family]:
            hit = False
            if family == "F블록" and k in HEAD_WORDS:
                hit = True
            if family == "형태자질" and any(
                    k == p or k.startswith(p + "=") or k.startswith(p)
                    for p in HEAD_FEATURE_PREFIX):
                hit = True
            if hit and (family, k) not in picked:
                picked.add((family, k))
                head_rows.append((family, k, c))
    return summary, head_rows


def print_head_tracking(summary, head_rows, families):
    """머리 항목 추적 표. 명세가 "표로" 내라고 한 자리다."""
    print("\n      ── BotSim에서 주목이었던 항목이 fox8에서 어떻게 되었나 ──")
    print("        가족        앞주목    유지    약화  역방향  방향없음  검정불가")
    for f in families:
        s = summary.get(f) or {}
        print(f"        {lpad(f, 12)}{s.get('앞주목수', 0):>6}"
              f"{s.get('유지', 0):>8}{s.get('약화', 0):>8}"
              f"{s.get('역방향', 0):>8}{s.get('방향 없음', 0):>10}"
              f"{s.get('검정불가', 0):>10}")
    print("        (유지 = 부호 같고 |δ_fox8| ≥ "
          f"{DELTA_NOTABLE} · 약화 = 부호 같고 그 미만 ·")
    print("         역방향 = 부호 반대. '무너짐'이라 쓰지 않는 이유는")
    print("         pair_with_baseline 의 주석에 적었다.)")

    print("\n      ── 명세가 지목한 머리 항목 ──")
    print("        가족        항목            BotSim δ   fox8 δ   단독AUC"
          "        q  추적")
    for family, k, c in head_rows:
        if c["fox8델타"] is None or c["BotSim델타"] is None:
            print(f"        {lpad(family, 12)}{k:<16}{'—':>9}{'—':>9}"
                  f"{'—':>9}{'—':>9}  {c['추적']}")
            continue
        print(f"        {lpad(family, 12)}{k:<16}{c['BotSim델타']:>+9.3f}"
              f"{c['fox8델타']:>+9.3f}{c['단독AUC']:>9.3f}{c['q']:>9.4f}  "
              f"{c['추적']}")
    print()
    print("        봉인 라인 치명 1이 적은 fox8 값과 견주어 보라 — such "
          f"{SEALED_BROKEN['such']} ·")
    print(f"        we {SEALED_BROKEN['we']} · must {SEALED_BROKEN['must']}"
          " (모두 AUC 값이다). 그때의 절차와 지금의 절차가")
    print("        달라 수치가 그대로 맞을 이유는 없지만, 같은 방향으로 무너졌는지")
    print("        아닌지는 읽을 수 있다.")


# ════════════════════════════════════════════════════════════════════════
# [7] 산포 — 09의 Brown-Forsythe와 쌍거리  [09·11에서 그대로 가져옴]
# ════════════════════════════════════════════════════════════════════════
def iqr_of(values):
    """사분위 범위 Q3 − Q1. [09에서 가져옴] 값이 둘 미만이면 0.0."""
    if len(values) < 2:
        return 0.0
    q = quartiles(values)
    return q["Q3"] - q["Q1"]


def abs_deviations(values):
    """
    그 무더기의 **자기 중앙값**에서 잰 절대편차. [09에서 가져옴] Brown-Forsythe의 재료다.

    ■ 왜 그룹별 중앙값인가 ■
    두 무더기를 합친 공통 중앙값을 쓰면, 위치가 다른 무더기는 그것만으로
    편차가 커진다. 그러면 표에는 '산포가 크다'로 찍히지만 실제로 잰 것은
    '위치가 다르다'다. 각 무더기에서 자기 중앙값을 빼면 두 무더기가 같은
    자리로 옮겨진 뒤 흩어짐만 남는다.

    반환된 편차들의 중앙값이 곧 그 무더기의 MAD다.
    """
    med = statistics.median(values)
    return [abs(v - med) for v in values], med


def brown_forsythe(v1, v2, subj="봇이"):
    """
    두 무더기의 산포를 견준다. 그룹1 기준. [09에서 가져옴 · 주어만 인자로]

        1. 각 무더기에서 그 무더기의 중앙값을 뺀 절대편차를 만든다.
        2. 두 절대편차 무더기를 Mann-Whitney U로 견주고 Cliff's δ를 낸다.
        3. δ < 0  →  그룹1의 절대편차가 작다  =  그룹1이 더 뭉쳐 있다.

    IQR·MAD·중앙값을 함께 담아 돌려준다. 검정이 "어느 쪽이 넓은가"만
    말한다면 IQR·MAD는 "얼마나 넓은가"를 말한다. 둘 다 있어야 읽힌다.
    한쪽이 비면 None을 돌려준다(검정 불가).
    """
    if not v1 or not v2:
        return None
    d1, m1 = abs_deviations(v1)
    d2, m2 = abs_deviations(v2)
    res = mann_whitney(d1, d2)
    iqr1, iqr2 = iqr_of(v1), iqr_of(v2)
    return {
        "검정가능": True,
        "U": res["U"], "z": res["z"], "p": res["p"],
        "델타": res["델타"], "방향": direction_disp(res["델타"], subj),
        "그룹1_중앙": m1, "그룹2_중앙": m2,
        "그룹1_IQR": iqr1, "그룹2_IQR": iqr2,
        "그룹1_MAD": statistics.median(d1), "그룹2_MAD": statistics.median(d2),
        # 비는 언제나 그룹2(사람) ÷ 그룹1이다. 1보다 크면 사람이 넓다.
        # 그룹1의 IQR이 0이면 나눗셈이 성립하지 않아 None — '무한대'가 아니라
        # '이 자료로는 비를 말할 수 없다'로 읽어야 한다.
        "IQR비": (iqr2 / iqr1) if iqr1 > 0 else None,
        "MAD비": (statistics.median(d2) / statistics.median(d1))
                if statistics.median(d1) > 0 else None,
        "그룹1_유효n": len(v1), "그룹2_유효n": len(v2),
    }


def pack_disp(r):
    """산포 결과 한 칸을 JSON에 담을 꼴로 바꾼다. [09의 pack_one · 11 경유]"""
    if r is None or not r.get("검정가능"):
        return {"검정가능": False, "델타": None, "q": None, "방향": "검정 불가"}
    return {
        "검정가능": True,
        "U": rnd(r["U"], 1), "z": rnd(r["z"], STAT_DIGITS),
        "p": sig(r["p"]), "q": sig(r["p"]),
        "q비고": "가족 밖 단독 검정이라 q = p (m = 1 에서 BH는 항등).",
        "델타": rnd(r["델타"], STAT_DIGITS), "방향": r["방향"],
        "그룹1_중앙": rnd(r["그룹1_중앙"], RATE_DIGITS),
        "그룹2_중앙": rnd(r["그룹2_중앙"], RATE_DIGITS),
        "그룹1_IQR": rnd(r["그룹1_IQR"], RATE_DIGITS),
        "그룹2_IQR": rnd(r["그룹2_IQR"], RATE_DIGITS),
        "그룹1_MAD": rnd(r["그룹1_MAD"], RATE_DIGITS),
        "그룹2_MAD": rnd(r["그룹2_MAD"], RATE_DIGITS),
        "IQR비": rnd(r["IQR비"], STAT_DIGITS),
        "MAD비": rnd(r["MAD비"], STAT_DIGITS),
        "그룹1_유효n": r["그룹1_유효n"], "그룹2_유효n": r["그룹2_유효n"],
    }


def dense_vectors(uids, rates, words):
    """
    계정마다 172차원 사용률 벡터를 만든다. [09에서 가져옴] 희소 저장을 조밀하게 편다.

    없는 키는 0.0이다 — word_vector()와 같은 규율이고 같은 이유다. 안 쓴
    단어를 빠뜨리면 벡터의 길이가 계정마다 달라져 거리를 잴 수 없다.
    """
    return [[rates[u]["사용률"].get(w, 0.0) for w in words] for u in uids]


def within_group_distances(vecs):
    """
    한 무더기 안의 모든 계정쌍 L1 거리. [09에서 가져옴] n개면 n(n−1)/2 쌍이다.

        L1(a, b) = Σ_j |a_j − b_j|          (172개 성분의 절대차 합)

    ■ 왜 L1인가 ■
    유클리드(L2)는 큰 성분 하나에 제곱으로 끌려간다. 172종 중 the·of·to
    같은 몇 단어가 사용률의 대부분을 차지하므로, L2를 쓰면 사실상 그 몇
    단어의 거리가 된다. L1은 모든 성분을 같은 무게로 더한다.

    ■ 반환 ■ (모든 쌍 거리 목록, 계정별 거리 목록)

    ■ 속도 ■ fox8은 두 무더기가 각각 천 계정을 넘는다. 봇 1,100이면 60만
    쌍, 사람 1,080이면 58만 쌍이다. 172성분을 곱하면 2억 번대의 뺄셈이라
    몇십 초가 걸린다. [9/9]가 미리 규모를 찍고 시간을 잰다.
    """
    n = len(vecs)
    dists = []
    per = [[] for _ in range(n)]
    for i in range(n - 1):
        vi = vecs[i]
        pi = per[i]
        for j in range(i + 1, n):
            d = sum(abs(a - b) for a, b in zip(vi, vecs[j]))
            dists.append(d)
            pi.append(d)
            per[j].append(d)
    return dists, per


def pile_table(name_values):
    """
    무더기별 다섯 숫자와 IQR·MAD를 한 표로 찍는다. [11에서 가져옴]

    name_values — [(무더기 이름, 값 목록), ...] 순서대로 찍는다.
    반환: {이름: {n, 중앙, IQR, MAD, 다섯숫자}}
    """
    out = {}
    print("        무더기          계정      중앙       IQR       MAD")
    for name, vals in name_values:
        if not vals:
            print(f"        {lpad(name, 12)}{0:>7,}   (비어 있음)")
            out[name] = {"n": 0, "중앙": None, "IQR": None, "MAD": None,
                         "다섯숫자": five_number([])}
            continue
        med = statistics.median(vals)
        devs, _ = abs_deviations(vals)
        mad = statistics.median(devs)
        iqr = iqr_of(vals)
        print(f"        {lpad(name, 12)}{len(vals):>7,}{med:>10.4f}"
              f"{iqr:>10.4f}{mad:>10.4f}")
        out[name] = {"n": len(vals), "중앙": rnd(med, RATE_DIGITS),
                     "IQR": rnd(iqr, RATE_DIGITS), "MAD": rnd(mad, RATE_DIGITS),
                     "다섯숫자": {k: rnd(v, RATE_DIGITS)
                              for k, v in five_number(vals).items()}}
    return out


# ════════════════════════════════════════════════════════════════════════
# [사슬] 다섯 파일이 같은 04에서 나왔는가  [11에서 그대로 가져옴]
# ════════════════════════════════════════════════════════════════════════
def chain_fingerprints(conf04, conf05, conf06, conf07, conf09):
    """
    04의 기능어 지문을 승계하고, 05·06·07·09가 적어 둔 값과 대조한다.
    [10·11의 chain_fingerprints 그대로]

    이 해시는 12가 쓰는 수치의 출처가 아니라 **04 실행분의 신분증**이다.
    12는 fox8을 새로 파싱하지만, 대조할 기준선(06의 δ, 07의 δ, 07의 축분류,
    09의 산포 δ)이 전부 04에서 나온 값이다. 기준선들이 서로 다른 04에서
    나왔다면 12는 어긋난 자들 사이에서 비교를 하게 되고, 화면에는 아무
    이상도 안 찍힌다. 그래서 중단이다.

    저장 자리가 파일마다 다르므로 각각 다른 경로로 꺼낸다.
        05 : 설정 → 04승계 → 기능어_해시
        06 : 설정 → 05승계 → 04승계 → 기능어_해시
        07 : 설정 → 04승계 → 기능어_해시
        09 : 설정 → 사슬확인 → 기능어_해시

    반환: (기록용 사전, 모두 일치하는가)
    """
    h04 = conf04.get("기능어_해시")
    h05 = (conf05.get("04승계") or {}).get("기능어_해시")
    h06 = ((conf06.get("05승계") or {}).get("04승계") or {}).get("기능어_해시")
    h07 = (conf07.get("04승계") or {}).get("기능어_해시")
    chain09 = conf09.get("사슬확인") or {}
    h09 = chain09.get("기능어_해시")
    seen = [h04, h05, h06, h07, h09]
    agree = all(h is not None for h in seen) and len(set(seen)) == 1
    return {
        "기능어_해시": h04,
        "기능어_개수": conf04.get("기능어_개수"),
        "04_실행일": conf04.get("실행일"),
        "05_실행일": conf05.get("실행일"),
        "06_실행일": conf06.get("실행일"),
        "07_실행일": conf07.get("실행일"),
        "09_실행일": conf09.get("실행일"),
        "05가_적어둔_해시": h05,
        "06이_적어둔_해시": h06,
        "07이_적어둔_해시": h07,
        "09가_적어둔_해시": h09,
        "09의_자체판정": chain09.get("일치"),
        "일치": agree,
    }


# ════════════════════════════════════════════════════════════════════════
# [8] 완화 B — 계정 내 전후 대조의 쌍 차이와 Wilcoxon
# ────────────────────────────────────────────────────────────────────────
# ■ 왜 계정 내 비율의 차이를 보나 ■
# 전·후 문서 수가 계정마다 다르다(전 10~109건, 후는 최대 200건). 두 쪽의
# 카운트를 그대로 빼면 문서 수 차이가 그대로 차이로 나온다. 그래서 사전선언
# 12가 못 박은 대로 **각각 계정 안에서 비율을 내고 그 비율의 쌍 차이를**
# 검정한다. 비율의 분모 규칙은 주 비교와 완전히 같다(05·07의 규칙).
#
# ■ 결측 처리 ■
# 어느 한쪽에서 분모가 0이면 그 항목의 그 계정 쌍만 빠진다. 계정이 통째로
# 빠지는 것이 아니라 칸 하나가 빠지는 것이고, 그래서 항목마다 쌍의 수가
# 다르다. 표에 그 수를 싣는다 — 07의 '유효 n'과 같은 성격이다.
# ════════════════════════════════════════════════════════════════════════
def paired_family(keys, uids, pre_rows, post_rows, kinds=None):
    """
    한 가족의 모든 항목에 Wilcoxon 부호순위를 걸고 BH를 건다.

    pre_rows · post_rows — {uid: {항목: 값 또는 None}}
    반환: (|r| 내림차순 (키, 결과) 목록, 검정 가능 항목 수)
    """
    rows = []
    for k in keys:
        diffs, used = [], []
        for u in uids:
            a = (pre_rows.get(u) or {}).get(k)
            b = (post_rows.get(u) or {}).get(k)
            if a is None or b is None:
                continue
            diffs.append(b - a)
            used.append(u)
        r = {
            "축": axis_of(k),
            "분모종류": (kinds or {}).get(k, DENOM_TOKEN),
            "쌍수": len(diffs),
            "결측쌍수": len(uids) - len(diffs),
        }
        w = wilcoxon_signed_rank(diffs) if diffs else None
        if w is None:
            r.update({"검정가능": False, "n": 0, "Wplus": None,
                      "Wminus": None, "z": None, "p": None, "q": None,
                      "r": None, "0쌍수": len(diffs), "합검산": None,
                      "검정력부족": True, "방향": "검정 불가",
                      "차이중앙": None, "차이Q1": None, "차이Q3": None,
                      "유의": False, "주목": False})
        else:
            q5 = quartiles(diffs)
            r.update({"검정가능": True, "n": w["n"], "Wplus": w["Wplus"],
                      "Wminus": w["Wminus"], "z": w["z"], "p": w["p"],
                      "r": w["r"], "0쌍수": w["0쌍수"], "합검산": w["합검산"],
                      "검정력부족": w["검정력부족"],
                      "방향": ("후가 높음" if w["r"] > 0 else
                             ("후가 낮음" if w["r"] < 0 else "차이 없음")),
                      "차이중앙": q5["중앙"], "차이Q1": q5["Q1"],
                      "차이Q3": q5["Q3"]})
        rows.append((k, r))

    testable = [(k, r) for k, r in rows if r["검정가능"]]
    qs = bh_qvalues([r["p"] for _, r in testable])
    for (k, r), q in zip(testable, qs):
        r["q"] = q
        r["유의"] = q <= Q_ALPHA
        # 쌍 검정의 '주목'은 |r| 로 잰다. Cliff's δ 와 rank-biserial r 는
        # 둘 다 −1…+1 이고 뜻도 비슷해 같은 문턱을 쓴다 — 다른 문턱을 쓰면
        # 새 자유도가 하나 생긴다.
        r["주목"] = r["유의"] and abs(r["r"]) >= DELTA_NOTABLE

    rows.sort(key=lambda kv: -(abs(kv[1]["r"]) if kv[1]["검정가능"] else -1.0))
    return rows, len(testable)


def print_paired_table(rows, title, limit=TOP_SHOW):
    """완화 B의 항목 표. 쌍 차이의 중앙값·사분위수를 함께 싣는다."""
    print(f"\n      {title}")
    shown = [kv for kv in rows if kv[1]["검정가능"]][:limit]
    if not shown:
        print("      검정 가능한 항목이 없습니다.")
        return
    print("      항목             쌍   0쌍       W+       W−        z"
          "        q       r   차이중앙   방향")
    for k, r in shown:
        mark = "  ← 검정력 부족" if r["검정력부족"] else ""
        print(f"      {k:<14}{r['쌍수']:>5}{r['0쌍수']:>5}"
              f"{r['Wplus']:>9.1f}{r['Wminus']:>9.1f}{r['z']:>9.3f}"
              f"{r['q']:>9.4f}{r['r']:>+8.3f}{r['차이중앙']:>+11.5f}   "
              f"{r['방향']}{mark}")


def paired_summary(rows, n_family, label):
    """완화 B 가족 하나의 요약."""
    sig_n = sum(1 for _, r in rows if r["유의"])
    notable = [(k, r) for k, r in rows if r["주목"]]
    up = sum(1 for _, r in notable if r["r"] > 0)
    down = sum(1 for _, r in notable if r["r"] < 0)
    weak = sum(1 for _, r in rows if r["검정가능"] and r["검정력부족"])
    bad_sum = sum(1 for _, r in rows if r["합검산"] is False)
    print(f"\n      [{label}] BH 가족 크기 {n_family}종 / {len(rows)}종 · "
          f"유의 {sig_n}종 · 주목(|r| ≥ {DELTA_NOTABLE}) {len(notable)}종")
    print(f"        후가 높음 {up}종 · 후가 낮음 {down}종 · "
          f"0 아닌 쌍이 {WILCOXON_MIN_N} 미만인 항목 {weak}종")
    if bad_sum:
        print(f"        ■ W+ + W− = n(n+1)/2 항등식이 깨진 항목 {bad_sum}종 — "
              "순위 계산을 보라.")
    return {"가족크기": n_family, "대상종수": len(rows), "유의": sig_n,
            "주목": len(notable), "후가높음": up, "후가낮음": down,
            "검정력부족": weak, "합검산_실패": bad_sum,
            "주목목록": [k for k, _ in notable]}


# ════════════════════════════════════════════════════════════════════════
# [9] 사람 출처 4분할 — 한 출처가 결과를 끌고 가는가
# ────────────────────────────────────────────────────────────────────────
# fox8의 '사람'은 단일 코호트가 아니다. botometer-feedback · gilani-17 ·
# midterm-2018 · varol-icwsm 은 수집 시기도 수집 기준도 다른 네 연구에서
# 왔다. 봇은 하나(fox8)뿐이므로 나뉘는 것은 대조군 쪽이다 — 11이 IRA를
# 유형별로 나눈 것과 방향이 반대다.
#
# ■ 출처별로는 q를 붙이지 않는다 ■ [11의 유형별 분해와 같은 판단]
# 출처 하나의 계정이 200~300개라 q는 나오기는 하지만, 네 무더기의 크기가
# 달라 q를 나란히 놓으면 '크기가 다르다'가 '신호가 다르다'로 읽힌다. 묻는
# 것은 방향이 갈리는가 하나뿐이므로 δ만 내고 상관을 본다.
#
# ■ 계정이 적은 출처 ■ SOURCE_MIN_N 미만이면 δ와 ρ를 계산해 표에 싣되
# '해석 금지' 표시를 붙이고 예측 6의 판정에서 뺀다. 계산을 아예 안 하면
# "계산해 봤더니 이상해서 뺐다"와 "처음부터 규칙이었다"를 구분할 수 없다.
# ════════════════════════════════════════════════════════════════════════
def source_delta_vectors(bot_ids, human_by_source, getters, keysets, min_n):
    """
    사람 출처별로 δ 벡터를 따로 낸다. 그룹1은 언제나 fox8 봇 전체다.

    getters — {가족: 값 꺼내는 함수}, keysets — {가족: 키 목록}
    반환: {출처: {계정수, 해석가능, 델타: {가족: {키: δ}}}}
    """
    out = {}
    for src in sorted(human_by_source, key=lambda s: -len(human_by_source[s])):
        ids = human_by_source[src]
        rec = {"계정수": len(ids), "해석가능": len(ids) >= min_n, "델타": {}}
        for family, keys in keysets.items():
            getter = getters[family]
            deltas = {}
            for k in keys:
                v1 = getter(bot_ids, k)
                v2 = getter(ids, k)
                if not v1 or not v2:
                    continue
                deltas[k] = rnd(mann_whitney(v1, v2)["델타"], STAT_DIGITS)
            rec["델타"][family] = deltas
        out[src] = rec
    return out


def source_correlations(source_deltas, baselines):
    """
    출처별 δ 벡터와 BotSim δ 벡터의 Spearman 상관·방향 일치율. [11에서 가져옴]

    baselines — {가족: {키: 기준선 사전}}. 06·07의 JSON을 그대로 받는다.
    반환: {출처: {계정수, 해석가능, 가족별: {가족: {항목수, rho, 방향일치율}}}}
    """
    out = {}
    for src, rec in source_deltas.items():
        fam_out = {}
        for family, deltas in rec["델타"].items():
            base = baselines.get(family) or {}
            xs, ys = [], []
            for k, d_new in deltas.items():
                d_old = (base.get(k) or {}).get("델타")
                if d_old is None or d_new is None:
                    continue
                xs.append(d_old)
                ys.append(d_new)
            judged = sum(1 for x, y in zip(xs, ys) if x != 0.0 and y != 0.0)
            same = sum(1 for x, y in zip(xs, ys)
                       if x != 0.0 and y != 0.0 and (x > 0) == (y > 0))
            fam_out[family] = {
                "항목수": len(xs),
                "rho": rnd(spearman(xs, ys), STAT_DIGITS),
                "방향일치율": rnd(same / judged, 4) if judged else None,
                "방향판정대상": judged,
            }
        out[src] = {"계정수": rec["계정수"], "해석가능": rec["해석가능"],
                    "가족별": fam_out}
    return out


def print_source_table(source_corr, families):
    """출처별 ρ 표. 계정이 적은 출처에는 표시를 붙인다."""
    print("\n      출처              계정" + "".join(rpad(f, 14) for f in families)
          + rpad("F 방향일치", 14))
    for src, rec in sorted(source_corr.items(),
                           key=lambda kv: -kv[1]["계정수"]):
        cells = ""
        for f in families:
            rho = (rec["가족별"].get(f) or {}).get("rho")
            cells += f"{'—':>14}" if rho is None else f"{rho:>+14.4f}"
        rate = (rec["가족별"].get("F블록") or {}).get("방향일치율")
        rate_txt = f"{'—':>14}" if rate is None else f"{rate:>13.1%} "
        mark = "" if rec["해석가능"] else f"   ← {SOURCE_MIN_N}개 미만 · 해석 금지"
        print(f"      {src:<16}{rec['계정수']:>6}{cells}{rate_txt}{mark}")
    print("\n      (칸의 수는 그 출처를 대조군으로 삼아 낸 δ 벡터와 BotSim δ")
    print("       벡터의 Spearman ρ다. 그룹1은 언제나 fox8 봇 전체다.")
    print(f"       계정 {SOURCE_MIN_N}개 미만인 출처는 우연으로 어디든 갈 수 있어")
    print("       예측 6의 판정에서 뺀다 — 표에는 남긴다.)")


def print_survival_table(survival):
    """
    출처별 생존율. 사전선언 12 판정 4가 "반드시 보고"하라고 한 자리다.

    계정 단위 영어 판정은 계정 하나를 통째로 버린다. 그래서 비영어 계정이
    많은 출처는 생존율이 크게 떨어지고, 그만큼 '사람'이라는 무더기의 구성이
    바뀐다. 바뀐 구성으로 낸 δ를 "fox8 사람과의 차이"라고 부르면 안 된다 —
    "01의 관문을 통과한 fox8 사람과의 차이"다.
    """
    print("\n      ── 출처별 생존율 (01의 관문을 몇 계정이 통과했나) ──")
    print("        출처                원본    적격   생존율   비영어탈락")
    for src, s in sorted(survival.items(), key=lambda kv: -kv[1]["원본계정"]):
        rate = "—" if s["생존율"] is None else f"{s['생존율']:.1%}"
        print(f"        {src:<18}{s['원본계정']:>7,}{s['적격계정']:>8,}"
              f"{rate:>9}{s['비영어탈락']:>13,}")
    rates = [s["생존율"] for s in survival.values() if s["생존율"] is not None]
    if len(rates) >= 2:
        span = max(rates) - min(rates)
        print(f"\n        생존율 폭 {span:.1%} "
              f"(최고 {max(rates):.1%} · 최저 {min(rates):.1%})")
        if span >= 0.10:
            print("        ■ 출처마다 10%p 넘게 다르다. 계정 단위 영어 판정이")
            print("          '사람' 무더기의 구성을 바꾸었다는 뜻이다. 사전선언")
            print("          12 판정 4가 보고하라고 한 그 사실이다 — [9/9]의")
            print("          출처 4분할을 이 사실과 함께 읽어야 한다.")
        else:
            print("        출처 간 차이가 10%p 미만이다. 구성이 크게 바뀌지는")
            print("        않았다.")


# ════════════════════════════════════════════════════════════════════════
# [10] 사전 예측 대조
# ════════════════════════════════════════════════════════════════════════
def print_prediction_header():
    """[9/9]의 머리말. 사전등록이 무엇을 막는지 매번 다시 적는다. [09·10·11에서]"""
    print("\n      사전선언 12의 예측 여섯을 실제 결과와 대조한다.")
    print("      아래 예측은 12를 돌리기 전에 문서에 확정된 것이다. 빗나간 예측도")
    print("      지우거나 고치지 않고 그대로 싣는다 — 06에서 라벨을 연 이상")
    print("      이 파이프라인에 남은 보호막은 사전등록뿐이다.")


def print_pred_meta(pred):
    """예측 하나의 서술·판정규칙·근거를 미리 끊어 둔 줄 그대로 찍는다. [08·09·10·11]"""
    print()
    print(f"      예측 {pred['번호']}  {pred['서술']}")
    print(f"        [{pred['축']}]")
    print("        판정 규칙으로 적어 둔 것:")
    for ln in pred["판정규칙"]:
        print(f"          {ln}")
    print("        근거로 적어 둔 것:")
    for ln in pred["근거"]:
        print(f"          {ln}")


def verdict_of(n_pass, n_total):
    """전부 통과면 적중, 일부면 부분 적중, 하나도 아니면 빗나감. [11의 관례]"""
    if n_total and n_pass == n_total:
        return "적중"
    if n_pass:
        return "부분 적중"
    return "빗나감"


def check_pred1(corr_whole):
    """
    예측 1 — F 블록의 ρ가 0.30 이상인가.

    사전선언 12의 예측 1이 "F 블록에서"라고 못 박았으므로 판정 대상은 F
    블록 하나다. 다른 가족의 ρ도 표에 싣지만 판정에 넣지 않는다 — 넣으면
    사전선언에 없는 조건을 더하는 것이 된다.
    """
    rows = []
    for family, block in corr_whole.items():
        rho = block["rho"]
        rows.append({"가족": family, "rho": rho, "항목수": block["항목수"],
                     "방향일치율": block["방향일치율"],
                     "판정대상": family == "F블록",
                     "통과": rho is not None and rho >= PRED_RHO_MIN})
    target = [r for r in rows if r["판정대상"]]
    n_pass = sum(1 for r in target if r["통과"])
    return {"문턱": PRED_RHO_MIN, "가족별": rows, "판정대상": "F블록",
            "판정": verdict_of(n_pass, len(target)) if target else "판정불가"}


def check_pred2(conc, f_rows):
    """
    예측 2 — 단독 효과가 한 항목에 몰리는가. 치명 1의 재현 여부다.

    (가) 세 가족 통합 상위 AUC_CUM 종에서 1위 점유율 ≥ PRED2_TOP1_SHARE
    (나) F 블록 단독 AUC 1위가 치명 1이 지목한 낱말(`was`)이다
    둘 다면 적중, 하나만이면 부분 적중, 둘 다 아니면 빗나감.

    f_rows — auc_ranking 이 낸 목록에서 F 블록만 추린 것.
    """
    a_ok = bool(conc) and conc["1위점유율"] >= PRED2_TOP1_SHARE
    top3_ok = bool(conc) and conc["상위3점유율"] >= PRED2_TOP3_SHARE
    f_top = f_rows[0] if f_rows else None
    b_ok = bool(f_top) and f_top["항목"] == PRED2_WORD

    # 치명 1은 `was` 와 `he` 두 항목을 함께 지목했다(둘만으로 AUC 0.8449).
    # 판정에는 넣지 않지만 두 항목이 표의 어디에 앉았는지는 반드시 싣는다 —
    # 1위가 아니어도 상위에 나란히 있으면 그것도 편중의 한 모습이다.
    named = {}
    for want in (PRED2_WORD, PRED2_SECOND):
        for i, r in enumerate(f_rows, 1):
            if r["항목"] == want:
                named[want] = {"F블록순위": i, "AUC": r["AUC"],
                               "세기": round(r["세기"], 6), "델타": r["델타"]}
                break
        else:
            named[want] = None

    n_pass = int(a_ok) + int(b_ok)
    return {
        "가_1위점유율": None if not conc else conc["1위점유율"],
        "가_문턱": PRED2_TOP1_SHARE,
        "가_통과": a_ok,
        "참고_상위3점유율": None if not conc else conc["상위3점유율"],
        "참고_상위3문턱": PRED2_TOP3_SHARE,
        "참고_상위3통과": top3_ok,
        "나_F블록1위": None if not f_top else f_top["항목"],
        "나_F블록1위AUC": None if not f_top else f_top["AUC"],
        "나_지목낱말": PRED2_WORD,
        "나_통과": b_ok,
        "치명1이_지목한두항목": named,
        "F블록_상위5": [{"항목": r["항목"], "AUC": r["AUC"],
                     "세기": round(r["세기"], 6)} for r in f_rows[:5]],
        "봉인라인_대조": {"결합AUC": SEALED_TOP10_AUC,
                    "was_몫": SEALED_WAS_SHARE,
                    "was_he_AUC": SEALED_WAS_HE_AUC,
                    "비고": "치명 1의 몫은 결합 점수의 분해이고 12의 점유율은 "
                           "단독 AUC들의 크기 비다. 같은 양이 아니다."},
        "판정": verdict_of(n_pass, 2),
    }


def check_pred3(pairs_by_family):
    """
    예측 3 — Tense=Past 의 전이가 was 보다 안정적인가.

    (가) 두 항목 모두 부호 유지
    (나) |δ_fox8 − δ_BotSim| 이 Tense=Past 쪽이 was 쪽보다 작다
    """
    def pick(item):
        family, key = item
        c = dict(pairs_by_family[family]).get(key)
        if c is None or c["fox8델타"] is None or c["BotSim델타"] is None:
            return None
        return c

    cf = pick(PRED3_FEATURE)
    cw = pick(PRED3_WORD)
    if cf is None or cw is None:
        return {"판정": "판정불가",
                "사유": "Tense=Past 또는 was 를 12에서 재지 못했다",
                "형태자질": cf, "F블록": cw}

    a_ok = (cf["부호일치"] is True) and (cw["부호일치"] is True)
    move_f, move_w = abs(cf["차이"]), abs(cw["차이"])
    b_ok = move_f < move_w
    n_pass = int(a_ok) + int(b_ok)
    return {
        "형태자질_Tense=Past": {"BotSim델타": cf["BotSim델타"],
                            "fox8델타": cf["fox8델타"],
                            "변화량절대": rnd(move_f, STAT_DIGITS),
                            "부호일치": cf["부호일치"],
                            "단독AUC": cf["단독AUC"], "추적": cf["추적"]},
        "F블록_was": {"BotSim델타": cw["BotSim델타"], "fox8델타": cw["fox8델타"],
                    "변화량절대": rnd(move_w, STAT_DIGITS),
                    "부호일치": cw["부호일치"],
                    "단독AUC": cw["단독AUC"], "추적": cw["추적"]},
        "가_둘다_부호유지": a_ok,
        "나_자질이_덜움직임": b_ok,
        "판정": verdict_of(n_pass, 2),
    }


def check_pred4(bf_total, bf_dist, disp09_total, disp09_dist):
    """
    예측 4 — fox8에서도 봇이 더 뭉쳐 있는가(δ < 0).

    (가) 총사용률 Brown-Forsythe δ < 0
    (나) 계정별 거리 중앙값 검정 δ < 0
    """
    d_tot = None if bf_total is None else bf_total["델타"]
    d_dis = None if bf_dist is None else bf_dist["델타"]
    a_ok = d_tot is not None and d_tot < 0
    b_ok = d_dis is not None and d_dis < 0
    n_pass = int(a_ok) + int(b_ok)
    return {
        "총사용률_델타": rnd(d_tot, STAT_DIGITS),
        "총사용률_q": None if bf_total is None else sig(bf_total["p"]),
        "총사용률_IQR비": None if bf_total is None else rnd(bf_total["IQR비"],
                                                       STAT_DIGITS),
        "계정별거리_델타": rnd(d_dis, STAT_DIGITS),
        "계정별거리_q": None if bf_dist is None else sig(bf_dist["p"]),
        "BotSim_총사용률_델타": disp09_total.get("델타"),
        "BotSim_총사용률_IQR비": disp09_total.get("IQR비"),
        "BotSim_계정별거리_델타": disp09_dist.get("델타"),
        "가_총사용률_음수": a_ok,
        "나_계정별거리_음수": b_ok,
        "판정": verdict_of(n_pass, 2),
        "비고": "'방향 신호보다 잘 전이된다'는 자동 판정하지 않는다. 방향의 "
              "전이는 ρ로, 산포의 전이는 δ의 부호로 재는데 두 눈금이 달라 "
              "곧바로 견줄 수 없다. 두 값을 나란히 싣고 판정은 사람에게 남긴다.",
    }


def check_pred5(paired_rows_by_family):
    """
    예측 5 — 계정 내 전후 대조에서 Tense=Past 가 유의하게 감소하는가.

    (가) BH 보정 후 q ≤ 0.05
    (나) 쌍 차이(후 − 전)의 중앙값 < 0
    쌍이 성립하는 계정이 WILCOXON_MIN_N 미만이면 판정불가.
    """
    family, key = PRED5_ITEM
    r = dict(paired_rows_by_family.get(family) or []).get(key)
    if r is None or not r["검정가능"]:
        return {"판정": "판정불가", "사유": "완화 B에서 이 항목을 검정하지 못했다",
                "항목": f"{family}·{key}"}
    if r["n"] < WILCOXON_MIN_N:
        return {"판정": "판정불가",
                "사유": f"0 아닌 쌍이 {r['n']}개뿐이라 검정력이 없다",
                "항목": f"{family}·{key}", "쌍수": r["쌍수"], "n": r["n"]}
    a_ok = r["q"] is not None and r["q"] <= Q_ALPHA
    b_ok = r["차이중앙"] is not None and r["차이중앙"] < 0
    n_pass = int(a_ok) + int(b_ok)
    return {
        "항목": f"{family}·{key}",
        "쌍수": r["쌍수"], "n": r["n"], "0쌍수": r["0쌍수"],
        "Wplus": r["Wplus"], "Wminus": r["Wminus"],
        "z": rnd(r["z"], STAT_DIGITS), "q": sig(r["q"]),
        "r": rnd(r["r"], STAT_DIGITS),
        "차이중앙": rnd(r["차이중앙"], RATE_DIGITS),
        "차이Q1": rnd(r["차이Q1"], RATE_DIGITS),
        "차이Q3": rnd(r["차이Q3"], RATE_DIGITS),
        "가_유의": a_ok, "나_중앙값_음수": b_ok,
        "판정": verdict_of(n_pass, 2),
    }


def check_pred6(source_corr, family="F블록"):
    """
    예측 6 — 출처 4분할 중 적어도 하나는 방향이 어긋나는가.

    (가) 판정 대상 출처의 F 블록 ρ 폭(최대 − 최소)이 PRED6_RHO_RANGE 이상
    (나) 어떤 출처의 F 블록 방향 일치율이 PRED6_MATCH_FLOOR 미만
    """
    usable = {}
    for src, rec in source_corr.items():
        if not rec["해석가능"]:
            continue
        blk = rec["가족별"].get(family) or {}
        if blk.get("rho") is None:
            continue
        usable[src] = {"rho": blk["rho"], "방향일치율": blk.get("방향일치율")}
    if len(usable) < 2:
        return {"판정": "판정불가",
                "사유": f"계정 {SOURCE_MIN_N}개 이상이면서 ρ를 낼 수 있는 출처가 "
                      f"{len(usable)}개뿐이다",
                "판정대상": usable}

    rhos = {s: v["rho"] for s, v in usable.items()}
    hi_src = max(rhos, key=rhos.get)
    lo_src = min(rhos, key=rhos.get)
    span = rhos[hi_src] - rhos[lo_src]
    a_ok = span >= PRED6_RHO_RANGE

    low_match = {s: v["방향일치율"] for s, v in usable.items()
                 if v["방향일치율"] is not None
                 and v["방향일치율"] < PRED6_MATCH_FLOOR}
    b_ok = bool(low_match)
    n_pass = int(a_ok) + int(b_ok)
    return {
        "기준가족": family,
        "판정대상": usable,
        "최대": {"출처": hi_src, "rho": rhos[hi_src]},
        "최소": {"출처": lo_src, "rho": rhos[lo_src]},
        "폭": rnd(span, STAT_DIGITS),
        "폭문턱": PRED6_RHO_RANGE,
        "가_폭이_문턱이상": a_ok,
        "일치율문턱": PRED6_MATCH_FLOOR,
        "나_일치율_낮은출처": low_match,
        "나_통과": b_ok,
        "판정": verdict_of(n_pass, 2),
    }


