        "F 사용률을, 07의 분모 규칙(대립값 2 이상인 축은 축 내부 합, "
        "하나뿐이면 토큰수_구두점제외)으로 형태자질을, 토큰수_구두점제외로 "
        "UPOS를 냈다. 축 판별은 04 전체와 fox8(본 코퍼스 + 전 텍스트)을 합친 "
        "자료에서 유도하고 07의 축분류와 대조해 차이를 기록했다. 비교는 "
        "그룹1 = fox8 봇 · 그룹2 = fox8 사람으로, 06과 동일한 Mann-Whitney "
        "U(양측·동점 보정·연속성 보정) + Cliff's δ, 다중비교는 "
        f"Benjamini-Hochberg FDR q = {Q_ALPHA} 를 세 가족(F {len(words)}종 · "
        f"형태자질 {len(feat_keys)}종 · UPOS {len(upos_keys)}종)에 각각 별도로 "
        f"걸었다. 주목 = q ≤ {Q_ALPHA} 그리고 |δ| ≥ {DELTA_NOTABLE}. "
        "특징별 단독 AUC는 AUC = (δ+1)/2 로 환산했다 — Mann-Whitney의 U1이 "
        "곧 ROC-AUC의 분자이므로 분류기 없이 정확히 얻어지며 새 자유도가 "
        "생기지 않는다(사전선언 결정 0-2의 이행, 결정 3의 배제 유지). 방향 "
        "벡터 상관은 δ_BotSim(06·07)과 δ_fox8의 Spearman으로, 순위"
        "(ranks_with_ties)의 피어슨으로 구현했다. 완화 A는 사람 문서를 "
        "2019~2020년으로 한정해(MIN_DOCS 재적용) 같은 비교를 반복했고, "
